-- Capy Notebook — schema baseline.
--
-- Store.Migrate applies each numbered file in this directory once and records
-- the filename plus a sha256 in schema_migrations. After the first kept
-- database exists, do not edit this file: add 0002_….sql.
--
-- Demo rows live in dev_seed.sql. The streaming-abort cleanup is a Go boot
-- hook, not a migration.
--
-- Extensions: pgvector only. The retrieval chunk store below is owned by this
-- schema (it was LightRAG's before the in-house cutover), so every environment
-- that applies this file needs the vector type — hence pgvector/pgvector:pg16
-- everywhere, including the CI service container (.github/workflows/ci.yml).
CREATE EXTENSION IF NOT EXISTS vector;

-- ============================================================================
-- Identity, workspaces, content tree
-- ============================================================================

-- Product limits that vary by subscription plan. Gateway and ingest-worker
-- processes load the complete table once at startup; request paths never use
-- this table as a live configuration lookup. NULL owned_workspace_limit means
-- unlimited. The frontend keeps an explicit translated-display copy rather
-- than exposing this catalog through a public API.
CREATE TABLE IF NOT EXISTS plan_limits (
  plan_tier                 text PRIMARY KEY
    CHECK (plan_tier IN ('free', 'pro')),
  storage_limit_bytes       bigint NOT NULL CHECK (storage_limit_bytes > 0),
  credit_limit_micros       bigint NOT NULL CHECK (credit_limit_micros > 0),
  source_file_max_bytes     bigint NOT NULL CHECK (source_file_max_bytes > 0),
  material_revision_limit   int NOT NULL CHECK (material_revision_limit > 0),
  owned_workspace_limit     int CHECK (owned_workspace_limit > 0),
  files_per_workspace       int NOT NULL CHECK (files_per_workspace > 0),
  files_per_upload          int NOT NULL CHECK (files_per_upload > 0)
);
INSERT INTO plan_limits (
  plan_tier, storage_limit_bytes, credit_limit_micros,
  source_file_max_bytes, material_revision_limit, owned_workspace_limit,
  files_per_workspace, files_per_upload
) VALUES
  ('free', 100000000, 1000000000, 10485760, 3, NULL, 100, 20),
  ('pro', 1000000000, 20000000000, 31457280, 30, NULL, 100, 20)
ON CONFLICT (plan_tier) DO NOTHING;

-- The user row is a durable tombstone: application logic never deletes it.
-- Deletion soft-flags the row and scrubs its PII, which keeps preserved
-- authorship (comments, revisions, materials authored inside other people's
-- workspaces) pointing at a real referent, retains the Stripe customer mapping
-- for invoice history, and prevents free-tier re-registration churn.
--
-- email is nullable precisely because purge scrubs it; read paths must
-- COALESCE. The schema-level cascades below still allow a hard DELETE for
-- operational recovery, but nothing in the application performs one.
CREATE TABLE IF NOT EXISTS users (
  id                    text PRIMARY KEY,
  name                  text NOT NULL,
  email                 text,
  avatar_url            text,
  class_label           text,
  streak                int  NOT NULL DEFAULT 0,
  stripe_customer_id    text UNIQUE,
  subscription_status   text NOT NULL DEFAULT 'none',
  plan_tier             text NOT NULL DEFAULT 'free' REFERENCES plan_limits(plan_tier)
    CHECK (plan_tier IN ('free', 'pro')),
  locale                text NOT NULL DEFAULT 'en',
  -- Per-slot user model preference. The provider/model pair names the
  -- catalog model; its latest enabled version is resolved per request.
  -- populated from the registry slot default at account creation. Ingest,
  -- retrieval and captioning are operator-only and are never stored here.
  chat_model_provider_slug     text NOT NULL DEFAULT 'deepseek',
  chat_model_slug              text NOT NULL DEFAULT 'deepseek-v4-flash-vision-exp',
  generate_model_provider_slug text NOT NULL DEFAULT 'deepseek',
  generate_model_slug          text NOT NULL DEFAULT 'deepseek-v4-flash-vision-exp',
  -- Inline editor assistance (continue-writing, rewrite, the /complete
  -- copilot). Far higher call volume per user than chat, and each call is short,
  -- so this is the slot where an expensive choice costs the most relative to
  -- the value delivered — worth watching if credit burn looks wrong.
  editor_model_provider_slug   text NOT NULL DEFAULT 'deepseek',
  editor_model_slug            text NOT NULL DEFAULT 'deepseek-v4-flash-vision-exp',
  -- Open-question marking may use provider_slug='browser'. Browser models run
  -- in-tab and never resolve through model_configs.
  quiz_model_provider_slug     text NOT NULL DEFAULT 'deepseek',
  quiz_model_slug              text NOT NULL DEFAULT 'deepseek-v4-flash-vision-exp',
  -- Account lifecycle. deletion_requested_at starts the reactivation window;
  -- purge_after is when the purge job runs; deleted_at is set by the purge
  -- itself, after which the row is a scrubbed tombstone.
  -- lifecycle_generation changes when support restores an account. A deletion
  -- request must present the generation returned by its preflight so an older
  -- request cannot put the restored account back into deletion.
  lifecycle_generation bigint NOT NULL DEFAULT 0 CHECK (lifecycle_generation >= 0),
  deletion_requested_at timestamptz,
  purge_after           timestamptz,
  deleted_at            timestamptz,
  -- Suspension is enforced (all writes rejected) but nothing sets it yet;
  -- there is no automated suspension policy.
  suspended_at          timestamptz,
  suspended_reason      text,
  -- External identity deletion is retried independently after local purge.
  -- A successful Clerk user.deleted webhook records identity_deleted_at.
  identity_deleted_at   timestamptz,
  identity_delete_pending boolean NOT NULL DEFAULT false,
  identity_delete_attempts int NOT NULL DEFAULT 0 CHECK (identity_delete_attempts >= 0),
  identity_delete_not_before timestamptz,
  -- Self-service deletion closes the local gate before Clerk is called. These
  -- fields make a failed session sweep durable and block support restoration
  -- until every issued session has been revoked.
  session_revoke_pending boolean NOT NULL DEFAULT false,
  session_revoke_attempts int NOT NULL DEFAULT 0 CHECK (session_revoke_attempts >= 0),
  session_revoke_not_before timestamptz,
  session_revoke_last_error text NOT NULL DEFAULT '',
  -- Remains null until the one-time starter workspace has been created. A
  -- failed first-request provision can therefore be retried without creating
  -- a replacement after the user later deletes all of their workspaces.
  starter_workspace_provisioned_at timestamptz,
  created_at            timestamptz NOT NULL DEFAULT now(),
  updated_at            timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT users_model_refs_nonempty CHECK (
    chat_model_provider_slug <> '' AND chat_model_slug <> ''
    AND generate_model_provider_slug <> '' AND generate_model_slug <> ''
    AND editor_model_provider_slug <> '' AND editor_model_slug <> ''
    AND quiz_model_provider_slug <> '' AND quiz_model_slug <> ''
  ),
  CONSTRAINT users_purge_window_check
    CHECK (purge_after IS NULL OR deletion_requested_at IS NOT NULL),
  CONSTRAINT users_deleted_requires_request_check
    CHECK (deleted_at IS NULL OR deletion_requested_at IS NOT NULL),
  CONSTRAINT users_suspension_reason_check
    CHECK ((suspended_at IS NULL) = (suspended_reason IS NULL))
);
-- Per (user, model, slot). Switching models must not reuse another
-- model's effort: DeepSeek has no medium, Opus does.
CREATE TABLE IF NOT EXISTS user_model_reasoning (
  user_id    text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  provider_slug text NOT NULL,
  model_slug text NOT NULL,
  slot       text NOT NULL,
  thinking   text NOT NULL DEFAULT '',
  PRIMARY KEY (user_id, provider_slug, model_slug, slot),
  CONSTRAINT user_model_reasoning_slot_check CHECK (
    slot IN ('chat', 'generate', 'quiz')
  ),
  CONSTRAINT user_model_reasoning_thinking_check CHECK (
    thinking IN ('', 'instant', 'low', 'mid', 'high', 'max')
  )
);
-- Invite resolution looks users up by email, so live accounts must be unique on
-- it. Tombstones are excluded: a scrubbed row holds no email, and a deleted
-- account must not block the address from being used again.
CREATE UNIQUE INDEX IF NOT EXISTS users_email_active_uidx
  ON users(lower(email))
  WHERE deleted_at IS NULL AND email IS NOT NULL;
-- Keeps the purge sweep bounded.
CREATE INDEX IF NOT EXISTS users_purge_due_idx
  ON users(purge_after)
  WHERE deleted_at IS NULL AND purge_after IS NOT NULL;
CREATE INDEX IF NOT EXISTS users_identity_delete_due_idx
  ON users(identity_delete_not_before)
  WHERE identity_delete_pending;
CREATE INDEX IF NOT EXISTS users_session_revoke_due_idx
  ON users(session_revoke_not_before)
  WHERE session_revoke_pending;

-- Foreign keys onto users(id) follow one rule throughout this schema:
--
--   * the ownership / storage-accounting axis cascades, so a hard DELETE of a
--     user is never blocked and the bytes charged to them go with them;
--   * the authorship / attribution axis is nullable ON DELETE SET NULL, so
--     content that lives inside somebody else's workspace survives.
--
-- In practice the SET NULL branches never fire, because deletion is a soft flag
-- and the scrubbed tombstone keeps the reference intact. They exist so that a
-- hard delete degrades to "author unknown" instead of destroying other users'
-- data. Read paths must therefore treat a null author and a tombstoned author
-- identically ("Deleted user").
CREATE TABLE IF NOT EXISTS workspaces (
  id               text PRIMARY KEY,
  user_id          text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  name             text NOT NULL,
  description      text NOT NULL DEFAULT '' CHECK (char_length(description) <= 1000),
  color            text NOT NULL DEFAULT 'green',
  privacy          text NOT NULL DEFAULT 'private',
  -- Role granted to link/public visitors who are not explicit members.
  share_role       text NOT NULL DEFAULT 'viewer',
  auto_reparse     boolean NOT NULL DEFAULT true,
  auto_reindex     boolean NOT NULL DEFAULT true,
  -- The vector space this workspace's index lives in. Pinned once at creation
  -- from the registry embedding default and never changed afterwards: there is
  -- no reindex job, so ingest and query must keep resolving this exact pin for
  -- the lifetime of the workspace. Both sides read it from here rather than
  -- from a per-process default, which is what stops a redeploy or an operator
  -- retarget from embedding a query in a different space than the chunks it is
  -- compared against. Changing the registry default only affects workspaces
  -- created afterwards.
  --
  -- A clone inherits the source workspace's pin instead of taking the current
  -- default, because cloneRetrievalIndex copies vectors verbatim.
  --
  -- The default matches the seeded embedding row so fixtures and tests can
  -- insert a workspace without wiring a registry. It is a self-consistent
  -- choice, not a fallback: whatever value lands here is what ingest embeds
  -- with, so a stale default yields an older space, never a mixed one.
  embedding_provider_slug text NOT NULL DEFAULT 'deepinfra',
  embedding_model_slug    text NOT NULL DEFAULT 'Qwen/Qwen3-Embedding-4B',
  embedding_model_version int  NOT NULL DEFAULT 1,
  -- Width the pinned model emits. Selects the halfvec column size. The vector
  -- table itself is chosen by the exact provider/model/version pin,
  -- not by this width: two 2560-d models do not share a table.
  embedding_dim           int  NOT NULL DEFAULT 2560,
  created_at       timestamptz NOT NULL DEFAULT now(),
  last_accessed_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT workspaces_share_role_check
    CHECK (share_role IN ('viewer', 'commenter', 'editor')),
  CONSTRAINT workspaces_embedding_pin_check
    CHECK (embedding_provider_slug <> '' AND embedding_model_slug <> ''
      AND embedding_model_version > 0),
  -- Every value here must have a rag_chunk_vectors_<dim> table below.
  CONSTRAINT workspaces_embedding_dim_check
    CHECK (embedding_dim IN (2560))
);
CREATE INDEX IF NOT EXISTS workspaces_user_idx ON workspaces(user_id);
CREATE INDEX IF NOT EXISTS workspaces_privacy_idx ON workspaces(privacy) WHERE privacy = 'public';

CREATE TABLE IF NOT EXISTS chapters (
  id           text PRIMARY KEY,
  workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  name         text NOT NULL,
  position     int  NOT NULL DEFAULT 0,
  -- Redundant with the primary key, but it is the target every composite
  -- (chapter_id, workspace_id) foreign key below needs, which is what stops a
  -- file or material referencing a chapter in a different workspace.
  UNIQUE (id, workspace_id)
);
CREATE INDEX IF NOT EXISTS chapters_ws_idx ON chapters(workspace_id);

CREATE TABLE IF NOT EXISTS files (
  id                    text PRIMARY KEY,
  workspace_id          text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  -- Storage owner, derived from the workspace by trigger. This is the
  -- accounting axis, hence CASCADE.
  user_id               text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  -- Uploader. Attribution only: a collaborator's deletion must not remove
  -- files from a workspace they do not own.
  created_by            text REFERENCES users(id) ON DELETE SET NULL,
  chapter_id            text,
  name                  text NOT NULL,
  kind                  text NOT NULL DEFAULT 'pdf',
  -- Mixed file/material order within a chapter (and the unfiled bucket).
  -- clock_timestamp() so concurrent inserts do not collide on now().
  position              bigint NOT NULL DEFAULT
                          (floor(extract(epoch FROM clock_timestamp()) * 1000000)::bigint),
  size_bytes            bigint NOT NULL DEFAULT 0 CHECK (size_bytes >= 0),
  added_at              timestamptz NOT NULL DEFAULT now(),
	status                text NOT NULL DEFAULT 'ready',   -- pending | processing | ready | failed
  -- True after ingest has written retrieval chunks. Viewable files uploaded
  -- with parseMode=none (audio, store-only) stay false.
  indexed               boolean NOT NULL DEFAULT false,
  ever_parsed_successfully boolean NOT NULL DEFAULT false,
  parser                text,
  engine                text,
  blob_path             text,
  -- Exact LibreOffice PDF that Office parser coordinates were measured
  -- against. PDFs use blob_path directly and leave this null.
  preview_blob_path     text,
  url                   text,
  content               text,
  -- Local parse-bundle identity/debug state. The required parser-to-ingest
  -- handoff stays in the shared spool. A separate parse-bundles/* B2 cache key
  -- is owned by artifact_cache, so the blob-refcount trigger ignores this path.
  parsed_blob_path      text,
  parsed_fingerprint    text,
  parsed_parser_version text,
  -- Source-level image captions, audio transcripts, or document figure
  -- captions. Identity/debug only; artifact_cache owns the blob reference.
  caption_blob_path     text,
  -- Legacy multipart uploads have no provider ETag. Store that fence as the
  -- empty string so every cancellation path can compare it without NULL's
  -- three-valued semantics.
  source_etag           text NOT NULL DEFAULT '',
  -- sha256 of the uploaded bytes, written by the ingest worker before parse.
  -- A ready rag_contents row with the same hash is a donor: copy its index
  -- instead of paying for parsing again. Computed server-side from the object;
  -- a client-asserted hash would let anyone claim a document they do not have.
  source_sha256         text,
  -- sha256 of the parsed text, written by the ingest worker. Two uploads of the
  -- same document into one workspace are stored twice (they are two files the
  -- user can see and delete) but indexed once.
  content_hash          text,
  -- Browser editors replace the source behind the same logical file. The
  -- revision is the optimistic-concurrency token carried by an edit session.
  revision              bigint NOT NULL DEFAULT 1 CHECK (revision > 0),
  -- Preserve the original ingest choice so a browser edit can enqueue the
  -- replacement through the same pipeline without asking the user again.
  parse_mode            text NOT NULL DEFAULT 'none',
  caption_images        boolean NOT NULL DEFAULT false,
  UNIQUE (id, workspace_id),
  -- The column list on SET NULL is what makes this work: the default form would
  -- try to null workspace_id too, which is NOT NULL. Requires Postgres 15+.
  FOREIGN KEY (chapter_id, workspace_id)
    REFERENCES chapters(id, workspace_id) ON DELETE SET NULL (chapter_id)
);
CREATE INDEX IF NOT EXISTS files_ws_idx ON files(workspace_id);
CREATE INDEX IF NOT EXISTS files_chapter_idx ON files(chapter_id);
CREATE INDEX IF NOT EXISTS files_chapter_position_idx
  ON files(workspace_id, chapter_id, position);
CREATE INDEX IF NOT EXISTS files_user_idx ON files(user_id);
CREATE INDEX IF NOT EXISTS files_content_hash_idx ON files(workspace_id, content_hash);
CREATE INDEX IF NOT EXISTS files_source_sha256_idx ON files(source_sha256);

-- ============================================================================
-- Materials — the universal Plate-document envelope for study artifacts
-- (notes, quizzes, flashcards, mindmaps, diagrams).
-- ============================================================================

CREATE TABLE IF NOT EXISTS materials (
  id             text PRIMARY KEY,
  -- Author. Distinct from owner_user_id: an editor creating a note inside
  -- somebody else's workspace is the creator, while the workspace owner is
  -- charged for the bytes. Cascading this column would let a collaborator's
  -- account deletion destroy content out of the owner's workspace and silently
  -- drop the owner's storage counter, so it is attribution-only.
  created_by     text REFERENCES users(id) ON DELETE SET NULL,
  workspace_id   text REFERENCES workspaces(id) ON DELETE CASCADE,
  -- Storage owner: the workspace owner, or the creator for standalone
  -- materials. This is the accounting axis, hence CASCADE.
  owner_user_id  text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  workspace_name text NOT NULL DEFAULT '',
  -- Membership: which chapter the material is filed under in the workspace
  -- tree (mirrors files.chapter_id). Nullable = unfiled; unfiles on chapter
  -- delete. Orthogonal to scope_chapters/scope_file_names, which record
  -- generation provenance as display-name snapshots rather than references.
  chapter_id     text,
  kind           text NOT NULL,
  title          text NOT NULL DEFAULT '',
  content        jsonb NOT NULL DEFAULT
    '{"schemaVersion":1,"value":[{"type":"p","children":[{"text":""}]}]}'::jsonb,
  scope_chapters text[] NOT NULL DEFAULT '{}',
  scope_file_names text[] NOT NULL DEFAULT '{}',
  privacy        text NOT NULL DEFAULT 'private',
  color          text NOT NULL DEFAULT 'green',
  -- Mixed file/material order within a chapter (and the unfiled bucket).
  position       bigint NOT NULL DEFAULT
                   (floor(extract(epoch FROM clock_timestamp()) * 1000000)::bigint),
  size_bytes     bigint NOT NULL DEFAULT 0 CHECK (size_bytes >= 0),
  node_count     int NOT NULL DEFAULT 0 CHECK (node_count >= 0),
  max_depth      int NOT NULL DEFAULT 0 CHECK (max_depth >= 0),
  revision       bigint NOT NULL DEFAULT 1,
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now(),
  updated_by     text REFERENCES users(id) ON DELETE SET NULL,
  CONSTRAINT materials_kind_check
    CHECK (kind IN ('mindmap','diagram','quiz','flashcards','note')),
  CONSTRAINT materials_content_envelope_check CHECK (
    jsonb_typeof(content) = 'object'
    AND content->>'schemaVersion' = '1'
    AND jsonb_typeof(content->'value') = 'array'
  ),
  -- A standalone material has no workspace, so the composite chapter reference
  -- is only meaningful when it is filed in one.
  CONSTRAINT materials_chapter_requires_workspace_check
    CHECK (chapter_id IS NULL OR workspace_id IS NOT NULL),
  CONSTRAINT materials_workspace_visibility_check
    CHECK (workspace_id IS NULL OR privacy = 'private'),
  FOREIGN KEY (chapter_id, workspace_id)
    REFERENCES chapters(id, workspace_id) ON DELETE SET NULL (chapter_id)
);
CREATE INDEX IF NOT EXISTS materials_ws_idx ON materials(workspace_id, created_at DESC);
CREATE INDEX IF NOT EXISTS materials_chapter_idx ON materials(chapter_id);
CREATE INDEX IF NOT EXISTS materials_chapter_position_idx
  ON materials(workspace_id, chapter_id, position);
-- Generated artifacts (and notes) share one list per workspace; duplicate
-- titles are indistinguishable there. Standalone clones have no workspace.
CREATE UNIQUE INDEX IF NOT EXISTS materials_workspace_title_uidx
  ON materials (workspace_id, lower(btrim(title)))
  WHERE workspace_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS materials_privacy_idx ON materials(privacy, kind) WHERE privacy = 'public';
CREATE INDEX IF NOT EXISTS materials_creator_idx ON materials(created_by, kind, created_at DESC);
CREATE INDEX IF NOT EXISTS materials_owner_idx ON materials(owner_user_id, created_at DESC);

-- Popularity counters live off the source rows so a clone never takes a write
-- lock that can delay collaboration persistence or projection. Source deletion
-- takes the clone advisory lock before cascaded teardown and counter cleanup
-- instead of adding an FK row lock.
CREATE TABLE IF NOT EXISTS workspace_clone_counts (
  workspace_id text PRIMARY KEY,
  clone_count  int NOT NULL DEFAULT 0 CHECK (clone_count >= 0)
);
CREATE TABLE IF NOT EXISTS material_clone_counts (
  material_id text PRIMARY KEY,
  clone_count int NOT NULL DEFAULT 0 CHECK (clone_count >= 0)
);

CREATE TABLE IF NOT EXISTS material_revisions (
  material_id            text NOT NULL REFERENCES materials(id) ON DELETE CASCADE,
  -- One mutable snapshot per UTC day. Saves during the same day replace this
  -- row; materials.revision remains the per-mutation concurrency counter.
  version_date           date NOT NULL,
  revision               bigint NOT NULL,
  parent_revision        bigint,
  event_type             text NOT NULL DEFAULT 'create'
                           CHECK (event_type IN ('create','edit')),
  title                  text NOT NULL,
  content                jsonb NOT NULL,
  event_metadata         jsonb NOT NULL DEFAULT '{}'::jsonb
                           CHECK (jsonb_typeof(event_metadata) = 'object'),
  created_by             text REFERENCES users(id) ON DELETE SET NULL,
  created_at             timestamptz NOT NULL DEFAULT now(),
  CHECK (parent_revision IS NULL OR parent_revision < revision),
  PRIMARY KEY (material_id, version_date),
  UNIQUE (material_id, revision)
);

-- The encoded Y.Doc is the authoritative material-content state after lazy
-- initialization. materials.content is an asynchronously updated read model.
CREATE TABLE IF NOT EXISTS material_yjs_documents (
  material_id       text PRIMARY KEY REFERENCES materials(id) ON DELETE CASCADE,
  room_schema       integer NOT NULL DEFAULT 1 CHECK (room_schema > 0),
  state             bytea NOT NULL,
  stored_version    bigint NOT NULL DEFAULT 1 CHECK (stored_version > 0),
  projected_version bigint NOT NULL DEFAULT 0 CHECK (projected_version >= 0),
  projection_error  text,
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT now(),
  projected_at      timestamptz,
  CHECK (projected_version <= stored_version)
);
CREATE INDEX IF NOT EXISTS material_yjs_projection_pending_idx
  ON material_yjs_documents(updated_at)
  WHERE projected_version < stored_version;

-- ACL changes commit their collaboration invalidation in the same database
-- transaction. Delivery is leased and retried by the gateway; eviction_id is
-- stable across every retry so collaboration instances can deduplicate it.
CREATE TABLE IF NOT EXISTS collaboration_eviction_outbox (
  id              text PRIMARY KEY,
  channel         text NOT NULL CHECK (channel IN (
                    'capy:collaboration:evict',
                    'capy:collaboration:user-evict'
                  )),
  payload         jsonb NOT NULL CHECK (jsonb_typeof(payload) = 'object'),
  attempts        int NOT NULL DEFAULT 0 CHECK (attempts >= 0),
  available_at    timestamptz NOT NULL DEFAULT now(),
  lease_id        text,
  lease_expires_at timestamptz,
  last_error      text,
  created_at      timestamptz NOT NULL DEFAULT now(),
  CHECK ((lease_id IS NULL) = (lease_expires_at IS NULL))
);
CREATE INDEX IF NOT EXISTS collaboration_eviction_outbox_due_idx
  ON collaboration_eviction_outbox(available_at, created_at);

-- Per-card FSRS scheduling state (shape mirrors SrsState in src/api/types.ts),
-- keyed by the flashcard element id inside the material document.
CREATE TABLE IF NOT EXISTS card_stats (
  card_id     text PRIMARY KEY,
  material_id text NOT NULL REFERENCES materials(id) ON DELETE CASCADE,
  srs         jsonb NOT NULL,
  known       boolean NOT NULL DEFAULT false
);
CREATE INDEX IF NOT EXISTS card_stats_material_idx ON card_stats(material_id);
-- Raw-text index: (srs->>'due')::timestamptz cannot be indexed — the
-- text->timestamptz cast is only STABLE (timezone-dependent) and Postgres
-- requires IMMUTABLE index expressions. The stored values are uniform
-- ISO-8601 UTC strings, which sort chronologically.
CREATE INDEX IF NOT EXISTS card_stats_due_idx ON card_stats ((srs->>'due'));

-- Quiz attempts. `answers` is a map keyed by question id (mirrors the frontend
-- Answer union); `questions` is the snapshot taken at submit time so later
-- quiz edits don't distort historical results.
--
-- material_id is deliberately SET NULL rather than CASCADE. The question
-- snapshot and the denormalized quiz_name / workspace_name exist precisely so
-- an attempt outlives the quiz; deleting a quiz must not erase the score
-- history of everyone who took it. The user's own deletion does cascade, since
-- attempts are their personal history.
CREATE TABLE IF NOT EXISTS attempts (
  id             text PRIMARY KEY,
  user_id        text REFERENCES users(id) ON DELETE CASCADE,
  material_id    text REFERENCES materials(id) ON DELETE SET NULL,
  quiz_name      text NOT NULL DEFAULT '',
  workspace_name text NOT NULL DEFAULT '',
  chapters       text[] NOT NULL DEFAULT '{}',
  -- Points awarded / points possible. Half-points are allowed (open questions).
  correct        numeric NOT NULL DEFAULT 0,
  total          numeric NOT NULL DEFAULT 0,
  pct            int NOT NULL DEFAULT 0,
  answers        jsonb NOT NULL DEFAULT '{}',
  questions      jsonb NOT NULL DEFAULT '[]',
  taken_at       timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS attempts_user_idx ON attempts(user_id, taken_at DESC);
CREATE INDEX IF NOT EXISTS attempts_material_idx ON attempts(material_id);

-- Per-user mistakes pool backing the "Review mistakes" virtual quiz. `question`
-- is self-contained, so as with attempts the source quiz disappearing only
-- unlinks the row.
CREATE TABLE IF NOT EXISTS mistakes (
  user_id     text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  question_id text NOT NULL,
  material_id text REFERENCES materials(id) ON DELETE SET NULL,
  question    jsonb NOT NULL,
  updated_at  timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, question_id)
);
CREATE INDEX IF NOT EXISTS mistakes_user_idx ON mistakes(user_id, updated_at DESC);
CREATE INDEX IF NOT EXISTS mistakes_material_idx ON mistakes(material_id);

-- ============================================================================
-- Tags — per-user, per-kind catalog (deduped by name) + entity link table.
-- Reusing a tag references the same catalog row, so per-tag metadata (future
-- analytics) survives edits and outlives the entities that reference it.
-- ============================================================================

CREATE TABLE IF NOT EXISTS tags (
  id         text PRIMARY KEY,
  user_id    text REFERENCES users(id) ON DELETE CASCADE,
  kind       text NOT NULL,               -- 'workspace' | 'material'
  name       text NOT NULL,
  metadata   jsonb NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS tags_user_idx ON tags(user_id);
CREATE INDEX IF NOT EXISTS tags_name_idx ON tags(lower(name));  -- cross-user search
-- Catalog uniqueness: one tag name per user per kind (case-insensitive).
CREATE UNIQUE INDEX IF NOT EXISTS tags_user_kind_name_uidx
  ON tags(user_id, kind, lower(name));

-- Tag links. The reference used to be a polymorphic (kind, entity_id) pair with
-- no foreign key, which left a dangling row behind every workspace and material
-- delete. Real per-type columns make the cleanup a cascade instead of something
-- every delete path has to remember, and the CHECK keeps a row pointing at
-- exactly one entity.
--
-- Orphaned catalog rows are deliberately NOT collected: the tags table exists to
-- outlive the entities referencing it so per-tag metadata survives edits and
-- reuse, and a few hundred bytes per user is not worth the write amplification.
CREATE TABLE IF NOT EXISTS entity_tags (
  tag_id       text NOT NULL REFERENCES tags(id) ON DELETE CASCADE,
  workspace_id text REFERENCES workspaces(id) ON DELETE CASCADE,
  material_id  text REFERENCES materials(id) ON DELETE CASCADE,
  created_at   timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT entity_tags_single_entity_check
    CHECK (num_nonnulls(workspace_id, material_id) = 1)
);
CREATE UNIQUE INDEX IF NOT EXISTS entity_tags_workspace_uidx
  ON entity_tags(workspace_id, tag_id) WHERE workspace_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS entity_tags_material_uidx
  ON entity_tags(material_id, tag_id) WHERE material_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS entity_tags_tag_idx ON entity_tags(tag_id);

-- ============================================================================
-- Personal planner: labels, events, tasks, canvases
-- ============================================================================

CREATE TABLE IF NOT EXISTS labels (
  id      text PRIMARY KEY,
  -- Labels are user-owned calendar categories: ownership axis, so CASCADE.
  user_id text REFERENCES users(id) ON DELETE CASCADE,
  name    text NOT NULL,
  color   text NOT NULL DEFAULT 'green'
);
CREATE INDEX IF NOT EXISTS labels_user_idx ON labels(user_id);

CREATE TABLE IF NOT EXISTS events (
  id        text PRIMARY KEY,
  user_id   text REFERENCES users(id) ON DELETE CASCADE,
  title     text NOT NULL,
  start_at  timestamptz NOT NULL,
  end_at    timestamptz NOT NULL,
  location  text,
  note      text
);
CREATE INDEX IF NOT EXISTS events_user_idx ON events(user_id);

-- Event labels were a text[] of label ids with no referential integrity, so
-- deleting a label left every event referencing it holding a dead id. A join
-- table lets the cascade clean up after itself.
CREATE TABLE IF NOT EXISTS event_labels (
  event_id text NOT NULL REFERENCES events(id) ON DELETE CASCADE,
  label_id text NOT NULL REFERENCES labels(id) ON DELETE CASCADE,
  PRIMARY KEY (event_id, label_id)
);
CREATE INDEX IF NOT EXISTS event_labels_label_idx ON event_labels(label_id);

CREATE TABLE IF NOT EXISTS tasks (
  id       text PRIMARY KEY,
  user_id  text REFERENCES users(id) ON DELETE CASCADE,
  title    text NOT NULL,
  meta     text,
  done     boolean NOT NULL DEFAULT false,
  due_date timestamptz NOT NULL
);
CREATE INDEX IF NOT EXISTS tasks_user_idx ON tasks(user_id);

CREATE TABLE IF NOT EXISTS canvases (
  id         text PRIMARY KEY,
  user_id    text REFERENCES users(id) ON DELETE CASCADE,
  name       text NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  scene      jsonb
);
CREATE INDEX IF NOT EXISTS canvases_user_idx ON canvases(user_id);

-- ============================================================================
-- Collaboration: membership, invitations, notifications
-- ============================================================================

CREATE TABLE IF NOT EXISTS workspace_members (
  workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  user_id      text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role         text NOT NULL CHECK (role IN ('owner','editor','commenter','viewer')),
  created_at   timestamptz NOT NULL DEFAULT now(),
  updated_at   timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (workspace_id, user_id)
);
CREATE INDEX IF NOT EXISTS workspace_members_user_idx
  ON workspace_members(user_id, workspace_id);

-- Identity-bound invitations: created against a resolved user account
-- (invited_user_id); `email` is retained for display only.
CREATE TABLE IF NOT EXISTS workspace_invites (
  id              text PRIMARY KEY,
  workspace_id    text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  email           text NOT NULL,
  invited_user_id text REFERENCES users(id) ON DELETE CASCADE,
  role            text NOT NULL CHECK (role IN ('editor','commenter','viewer')),
  token_hash      bytea NOT NULL UNIQUE CHECK (octet_length(token_hash) = 32),
  invited_by      text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  accepted_by     text REFERENCES users(id) ON DELETE SET NULL,
  expires_at      timestamptz NOT NULL,
  accepted_at     timestamptz,
  revoked_at      timestamptz,
  created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS workspace_invites_pending_user_idx
  ON workspace_invites(workspace_id, invited_user_id)
  WHERE accepted_at IS NULL
    AND revoked_at IS NULL
    AND invited_user_id IS NOT NULL;
-- Keeps periodic invitation-expiry cleanup bounded.
CREATE INDEX IF NOT EXISTS workspace_invites_expiry_idx
  ON workspace_invites(expires_at)
  WHERE accepted_at IS NULL;

CREATE TABLE IF NOT EXISTS notifications (
  id                  text PRIMARY KEY,
  user_id             text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  kind                text NOT NULL,
  data                jsonb NOT NULL DEFAULT '{}'::jsonb
    CHECK (jsonb_typeof(data) = 'object'),
  href                text,
  workspace_id        text REFERENCES workspaces(id) ON DELETE CASCADE,
  -- Actionable, recipient-only workspace-invitation notifications.
  workspace_invite_id text REFERENCES workspace_invites(id) ON DELETE CASCADE,
  at                  timestamptz NOT NULL DEFAULT now(),
  read_at             timestamptz
);
-- Matches the (at,id) keyset cursor used for pagination; a plain
-- (user_id, at DESC) index would be a redundant prefix of this one.
CREATE INDEX IF NOT EXISTS notifications_user_at_id_idx
  ON notifications(user_id, at DESC, id DESC);
CREATE INDEX IF NOT EXISTS notifications_user_unread_idx
  ON notifications(user_id)
  WHERE read_at IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS notifications_workspace_invite_idx
  ON notifications(workspace_invite_id)
  WHERE workspace_invite_id IS NOT NULL;

-- Product mail is sent asynchronously from this transactional outbox. The
-- payload is cleared after a successful send because invite payloads contain
-- the one-time plaintext token.
CREATE TABLE IF NOT EXISTS email_outbox (
  id                   text PRIMARY KEY,
  user_id              text REFERENCES users(id) ON DELETE SET NULL,
  to_email             text NOT NULL,
  template             text NOT NULL,
  locale               text NOT NULL DEFAULT 'en',
  payload              jsonb NOT NULL DEFAULT '{}'::jsonb
    CHECK (jsonb_typeof(payload) = 'object'),
  idempotency_key      text UNIQUE,
  status               text NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'sending', 'sent', 'failed')),
  attempts             int NOT NULL DEFAULT 0 CHECK (attempts >= 0),
  next_attempt_at      timestamptz NOT NULL DEFAULT now(),
  provider_message_id  text,
  last_error           text,
  lease_token          text,
  lease_expires_at     timestamptz,
  created_at           timestamptz NOT NULL DEFAULT now(),
  updated_at           timestamptz NOT NULL DEFAULT now(),
  sent_at              timestamptz
);
CREATE INDEX IF NOT EXISTS email_outbox_claim_idx
  ON email_outbox(next_attempt_at)
  WHERE status = 'pending';
CREATE INDEX IF NOT EXISTS email_outbox_lease_idx
  ON email_outbox(lease_expires_at)
  WHERE status = 'sending';

CREATE TABLE IF NOT EXISTS notification_prefs (
  user_id                 text PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  email_workspace_invite  boolean NOT NULL DEFAULT true,
  email_membership        boolean NOT NULL DEFAULT true,
  -- Over-quota / billing buffer warnings. Lifecycle emails (deletion requested,
  -- purge) are always sent and do not consult this flag.
  email_billing           boolean NOT NULL DEFAULT true,
  updated_at              timestamptz NOT NULL DEFAULT now()
);

-- Idempotency for the buffer-period reminder schedule. Kind is scoped to one
-- subscription period_end so a later re-lapse can notify again.
CREATE TABLE IF NOT EXISTS lifecycle_notices (
  user_id    text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  kind       text NOT NULL,
  period_end timestamptz NOT NULL,
  sent_at    timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, kind, period_end)
);
CREATE INDEX IF NOT EXISTS lifecycle_notices_user_idx
  ON lifecycle_notices(user_id, sent_at DESC);

-- ============================================================================
-- Collaboration: comment discussions and comments
-- ============================================================================

CREATE TABLE IF NOT EXISTS material_discussions (
  id          text PRIMARY KEY,
  material_id text NOT NULL REFERENCES materials(id) ON DELETE CASCADE,
  block_id    text,
  anchor_start bytea,
  anchor_end   bytea,
  anchor_version integer NOT NULL DEFAULT 1 CHECK (anchor_version > 0),
  anchor_quote text NOT NULL DEFAULT '',
  -- Attribution axis: a discussion opened inside somebody else's document must
  -- not vanish because its author left.
  created_by  text REFERENCES users(id) ON DELETE SET NULL,
  is_resolved boolean NOT NULL DEFAULT false,
  deleted_at  timestamptz,
  deleted_by  text REFERENCES users(id) ON DELETE SET NULL,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  CHECK ((anchor_start IS NULL) = (anchor_end IS NULL)),
  CHECK (anchor_start IS NULL OR (octet_length(anchor_start) BETWEEN 1 AND 4096)),
  CHECK (anchor_end IS NULL OR (octet_length(anchor_end) BETWEEN 1 AND 4096)),
  CHECK (length(anchor_quote) <= 1000)
);
CREATE INDEX IF NOT EXISTS material_discussions_material_idx
  ON material_discussions(material_id, created_at) WHERE deleted_at IS NULL;

CREATE TABLE IF NOT EXISTS material_comments (
  id                text PRIMARY KEY,
  discussion_id     text NOT NULL REFERENCES material_discussions(id) ON DELETE CASCADE,
  parent_comment_id text REFERENCES material_comments(id) ON DELETE SET NULL,
  -- Attribution axis. See material_discussions.created_by.
  user_id           text REFERENCES users(id) ON DELETE SET NULL,
  content_rich      jsonb NOT NULL,
  is_edited         boolean NOT NULL DEFAULT false,
  deleted_at        timestamptz,
  deleted_by        text REFERENCES users(id) ON DELETE SET NULL,
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT now(),
  CHECK (parent_comment_id IS NULL OR parent_comment_id <> id)
);
CREATE INDEX IF NOT EXISTS material_comments_discussion_idx
  ON material_comments(discussion_id, created_at) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS material_comments_parent_idx
  ON material_comments(parent_comment_id, created_at) WHERE parent_comment_id IS NOT NULL;

-- ============================================================================
-- AI chat persistence. Conversations are workspace-scoped: grounding searches
-- the owning workspace's chunks, so every conversation carries both user_id
-- (ownership) and workspace_id (scope).
-- ============================================================================

CREATE TABLE IF NOT EXISTS conversations (
  id           text PRIMARY KEY,
  user_id      text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  title        text,
  metadata     jsonb NOT NULL DEFAULT '{}',   -- system prompt, RAG filters, etc.
  created_at   timestamptz NOT NULL DEFAULT now(),
  updated_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS conversations_ws_idx ON conversations(workspace_id, updated_at DESC);
CREATE INDEX IF NOT EXISTS conversations_user_idx ON conversations(user_id, updated_at DESC);

CREATE TABLE IF NOT EXISTS messages (
  id              text PRIMARY KEY,
  conversation_id text NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
  role            text NOT NULL CHECK (role IN ('user','assistant','system')),
  content         text NOT NULL DEFAULT '',
  status          text NOT NULL DEFAULT 'complete', -- streaming | complete | aborted | error
  token_count     int,
  metadata        jsonb NOT NULL DEFAULT '{}',       -- RAG citations, generation_id, usage
  created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS messages_conv_idx ON messages(conversation_id, created_at, id);
CREATE INDEX IF NOT EXISTS messages_ops_assistant_idx
  ON messages(created_at DESC, status)
  WHERE role = 'assistant';

-- Latest rolling summary for one conversation. through_message_id is the last
-- completed historical message folded into summary. A compare-and-set write
-- must not move that pin backwards when two tabs race.
CREATE TABLE IF NOT EXISTS conversation_compactions (
  conversation_id     text PRIMARY KEY REFERENCES conversations(id) ON DELETE CASCADE,
  through_message_id  text NOT NULL REFERENCES messages(id),
  summary             text NOT NULL,
  model_provider_slug text NOT NULL,
  model_slug          text NOT NULL,
  model_version       int  NOT NULL,
  estimated_tokens    int  NOT NULL DEFAULT 0,
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now()
);

-- ============================================================================
-- Auth/billing plumbing and the async job queue
-- ============================================================================

-- oauth_connections is gone: Clerk owns the OAuth lifecycle for provider
-- integrations and hands out fresh access tokens from its token wallet, so no
-- provider credentials are stored locally. Retaining tokens for deleted
-- accounts would also be a liability the purge path cannot discharge.

-- One row per Stripe subscription. users.plan_tier stays as the denormalized
-- fast read for the storage gate, but it is derived from here.
--
-- current_period_end is what makes the lapse buffer computable at all, and
-- stripe_event_created is the ordering guard: Stripe does not guarantee webhook
-- delivery order, so an older event must never overwrite newer state.
CREATE TABLE IF NOT EXISTS user_subscriptions (
  stripe_subscription_id text PRIMARY KEY,
  user_id                text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  status                 text NOT NULL,
  price_id               text NOT NULL DEFAULT '',
  plan_tier              text NOT NULL DEFAULT 'free' REFERENCES plan_limits(plan_tier)
    CHECK (plan_tier IN ('free', 'pro')),
  current_period_end     timestamptz,
  cancel_at_period_end   boolean NOT NULL DEFAULT false,
  canceled_at            timestamptz,
  ended_at               timestamptz,
  -- Stripe event `created` (unix seconds) that produced this row's state.
  stripe_event_created   bigint NOT NULL DEFAULT 0,
  created_at             timestamptz NOT NULL DEFAULT now(),
  updated_at             timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS user_subscriptions_user_idx
  ON user_subscriptions(user_id, current_period_end DESC);
-- Drives the lapse sweep: subscriptions whose paid period has run out.
CREATE INDEX IF NOT EXISTS user_subscriptions_period_end_idx
  ON user_subscriptions(current_period_end)
  WHERE current_period_end IS NOT NULL;

-- Checkout sessions are tracked locally so deletion/suspension races can
-- expire a remote session that was created immediately before the account was
-- locked. Completed sessions retain their subscription link for diagnostics.
CREATE TABLE IF NOT EXISTS stripe_checkout_sessions (
  id              text PRIMARY KEY,
  provider_session_id text UNIQUE,
  user_id         text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  customer_id     text NOT NULL DEFAULT '',
  price_id        text NOT NULL DEFAULT '',
  success_url     text NOT NULL DEFAULT '',
  cancel_url      text NOT NULL DEFAULT '',
  status          text NOT NULL DEFAULT 'creating'
    CHECK (status IN ('creating','open','completed','expired','failed')),
  subscription_id text,
  expires_at      timestamptz NOT NULL DEFAULT (now()+interval '24 hours'),
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now(),
  completed_at    timestamptz
);
CREATE UNIQUE INDEX IF NOT EXISTS stripe_checkout_sessions_user_open_idx
  ON stripe_checkout_sessions(user_id)
  WHERE status IN ('creating','open');

-- Durable, idempotent remote compensation. Account deletion and lifecycle-
-- aware webhook/reconciliation paths enqueue work in their database
-- transaction; an API worker retries Stripe mutations with a lease/backoff.
CREATE TABLE IF NOT EXISTS stripe_compensations (
  id               bigserial PRIMARY KEY,
  user_id          text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  action           text NOT NULL CHECK (action IN (
    'recover_checkout','expire_checkout','cancel_subscription',
    'refund_payment_intent','refund_charge'
  )),
  object_id        text NOT NULL,
  status           text NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending','running','succeeded','suppressed')),
  attempts         int NOT NULL DEFAULT 0 CHECK (attempts >= 0),
  generation       int NOT NULL DEFAULT 0 CHECK (generation >= 0),
  provider_result_id text,
  -- Set before a cancellation provider call begins. Restoration may suppress
  -- an unstarted claim, but must wait for a started/uncertain call to reconcile.
  provider_started_at timestamptz,
  next_attempt_at  timestamptz NOT NULL DEFAULT now(),
  lease_token      text,
  lease_expires_at timestamptz,
  last_error       text NOT NULL DEFAULT '',
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  completed_at     timestamptz,
  UNIQUE (action, object_id),
  CHECK (
    (status='running' AND lease_token IS NOT NULL AND lease_expires_at IS NOT NULL)
    OR (status<>'running' AND lease_token IS NULL AND lease_expires_at IS NULL)
  )
);
CREATE INDEX IF NOT EXISTS stripe_compensations_claim_idx
  ON stripe_compensations(next_attempt_at, id)
  WHERE status IN ('pending','running');

CREATE TABLE IF NOT EXISTS webhook_events (
  id           text NOT NULL,
  source       text NOT NULL,
  event_type   text NOT NULL,
  user_id      text REFERENCES users(id) ON DELETE SET NULL,
  payload      jsonb NOT NULL DEFAULT '{}',
  processing_token text,
  processing_started_at timestamptz,
  processed_at timestamptz,
  error        text,
  PRIMARY KEY (source, id)
);
CREATE INDEX IF NOT EXISTS webhook_events_source_idx ON webhook_events(source, processed_at);

-- Operator-managed product prices for resources that are not priced by model
-- tokens. A new version is inserted when a price changes; jobs keep the
-- version they were enqueued with so a queued upload is never repriced.
CREATE TABLE IF NOT EXISTS resource_credit_rates (
  resource_key            text NOT NULL,
  version                 int NOT NULL CHECK (version > 0),
  unit                    text NOT NULL,
  credit_micros_per_unit  bigint NOT NULL CHECK (credit_micros_per_unit >= 0),
  active                  boolean NOT NULL DEFAULT false,
  created_at              timestamptz NOT NULL DEFAULT now(),
  created_by              text REFERENCES users(id) ON DELETE SET NULL,
  PRIMARY KEY (resource_key, version)
);
CREATE UNIQUE INDEX IF NOT EXISTS resource_credit_rates_active_idx
  ON resource_credit_rates(resource_key) WHERE active;

INSERT INTO resource_credit_rates
  (resource_key, version, unit, credit_micros_per_unit, active)
VALUES
  ('audio_transcription_second', 1, 'second', 250000, true),
  ('digital_parse_page', 1, 'page', 31000000, true),
  ('ocr_parse_page', 1, 'page', 52000000, true),
  ('figure_caption_call', 1, 'call', 2000000, true),
  ('email_message', 1, 'message', 100000, true)
ON CONFLICT (resource_key, version) DO NOTHING;

-- Postgres-backed job queue for async ingestion (claimed via SKIP LOCKED).
CREATE TABLE IF NOT EXISTS jobs (
  id         text PRIMARY KEY,
  type       text NOT NULL,
  payload    jsonb NOT NULL DEFAULT '{}',
  status     text NOT NULL DEFAULT 'pending',  -- pending | running | done | failed
  attempts   int NOT NULL DEFAULT 0,
  -- Times a busy provider sent this job back to pending without spending an
  -- attempt. The worker fails the job past its cap.
  provider_waits int NOT NULL DEFAULT 0,
  error      text,
  locked_at  timestamptz,
  -- Claimable only once this instant has passed. Backoff after a retryable
  -- failure lives here rather than as a sleep in the worker, so a restart
  -- does not retry immediately.
  not_before timestamptz,
  -- Heartbeat deadline. A worker that dies mid-job leaves this in the past;
  -- the reaper turns the row pending (or failed, once the attempt budget is
  -- spent) instead of leaving it running forever.
  lease_expires_at timestamptz,
  -- Reset whenever the row re-enters the queue. Unlike created_at, this gives
  -- each retry an honest queue-wait duration.
  queued_at  timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS jobs_status_idx ON jobs(status, created_at);
CREATE INDEX IF NOT EXISTS jobs_claim_idx
  ON jobs(type, status, created_at)
  WHERE status = 'pending';
CREATE INDEX IF NOT EXISTS jobs_lease_idx
  ON jobs(lease_expires_at)
  WHERE status = 'running';

-- One durable row for every queue claim. A capacity wait
-- may undo jobs.attempts, so the generated id is the identity rather than the
-- visible attempt number. The lease reaper closes rows left running by a dead
-- process. Commonly charted values stay typed; stage_timings and details are
-- numeric/enum diagnostics only and never contain source content or file names.
CREATE TABLE IF NOT EXISTS ingest_job_attempts (
  id                    bigserial PRIMARY KEY,
  job_id                text NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,
  operation_id          text NOT NULL,
  attempt               integer NOT NULL CHECK (attempt > 0),
  job_type              text NOT NULL CHECK (job_type IN ('import', 'parse', 'ingest')),
  environment           text NOT NULL,
  host_id               text NOT NULL,
  worker_instance_id    text NOT NULL,
  release_sha           text NOT NULL DEFAULT '',
  trace_id              text NOT NULL,
  route                 text NOT NULL DEFAULT '',
  source_format         text NOT NULL DEFAULT '',
  status                text NOT NULL DEFAULT 'running'
    CHECK (status IN (
      'running', 'succeeded', 'retrying', 'failed', 'superseded',
      'lease_expired', 'capacity_wait', 'provider_busy'
    )),
  stage                 text NOT NULL DEFAULT 'claimed',
  error_category        text NOT NULL DEFAULT '',
  error_code            text NOT NULL DEFAULT '',
  error_detail          text NOT NULL DEFAULT '',
  retryable             boolean NOT NULL DEFAULT false,
  queued_at             timestamptz NOT NULL,
  claimed_at            timestamptz NOT NULL DEFAULT now(),
  finished_at           timestamptz,
  next_retry_at         timestamptz,
  queue_milliseconds    bigint NOT NULL DEFAULT 0 CHECK (queue_milliseconds >= 0),
  duration_milliseconds bigint NOT NULL DEFAULT 0 CHECK (duration_milliseconds >= 0),
  source_bytes          bigint NOT NULL DEFAULT 0 CHECK (source_bytes >= 0),
  artifact_bytes        bigint NOT NULL DEFAULT 0 CHECK (artifact_bytes >= 0),
  parse_pages           bigint NOT NULL DEFAULT 0 CHECK (parse_pages >= 0),
  parse_ocr_pages       bigint NOT NULL DEFAULT 0 CHECK (
    parse_ocr_pages >= 0 AND parse_ocr_pages <= parse_pages
  ),
  parse_slices          integer NOT NULL DEFAULT 0 CHECK (parse_slices >= 0),
  parser_queue_milliseconds bigint NOT NULL DEFAULT 0
    CHECK (parser_queue_milliseconds >= 0),
  parser_execution_milliseconds bigint NOT NULL DEFAULT 0
    CHECK (parser_execution_milliseconds >= 0),
  figures_selected      integer NOT NULL DEFAULT 0 CHECK (figures_selected >= 0),
  figures_cached        integer NOT NULL DEFAULT 0 CHECK (figures_cached >= 0),
  figures_captioned     integer NOT NULL DEFAULT 0 CHECK (figures_captioned >= 0),
  figures_decorative    integer NOT NULL DEFAULT 0 CHECK (figures_decorative >= 0),
  figures_applied       integer NOT NULL DEFAULT 0 CHECK (figures_applied >= 0),
  figures_failed        integer NOT NULL DEFAULT 0 CHECK (figures_failed >= 0),
  chunks_created        integer NOT NULL DEFAULT 0 CHECK (chunks_created >= 0),
  donor_reused          boolean NOT NULL DEFAULT false,
  stage_timings         jsonb NOT NULL DEFAULT '{}'::jsonb,
  details               jsonb NOT NULL DEFAULT '{}'::jsonb,
  CONSTRAINT ingest_job_attempts_trace_check CHECK (trace_id <> ''),
  CONSTRAINT ingest_job_attempts_worker_check CHECK (
    environment <> '' AND host_id <> '' AND worker_instance_id <> ''
  )
);
CREATE INDEX IF NOT EXISTS ingest_job_attempts_operation_idx
  ON ingest_job_attempts(operation_id, claimed_at DESC);
CREATE INDEX IF NOT EXISTS ingest_job_attempts_status_idx
  ON ingest_job_attempts(status, claimed_at DESC);
CREATE INDEX IF NOT EXISTS ingest_job_attempts_environment_idx
  ON ingest_job_attempts(environment, claimed_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS ingest_job_attempts_running_claim_idx
  ON ingest_job_attempts(job_id, attempt)
  WHERE status = 'running';

-- Synchronous provider calls still consume ElevenLabs' weighted concurrency.
-- Short durable leases keep separate worker processes within the configured
-- capacity and expire after a crashed worker. No transcript/provider state is
-- persisted: the POST response is awaited by the ingest attempt itself.
CREATE TABLE IF NOT EXISTS provider_capacity_leases (
  id         text PRIMARY KEY,
  provider   text NOT NULL,
  units      int NOT NULL CHECK (units > 0),
  expires_at timestamptz NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS provider_capacity_leases_provider_expiry_idx
  ON provider_capacity_leases(provider, expires_at);

-- ============================================================================
-- Retrieval store — chunks and per-file summaries
--
-- Owned by this schema (the Python pipeline writes the rows but no longer owns
-- the DDL), which is what makes deletion automatic: every table cascades from
-- workspaces/files/chapters, so dropping a workspace drops its index with it.
-- No teardown job, and cloning a workspace is an INSERT..SELECT away.
-- ============================================================================

-- Parsed content is canonical within a workspace. Multiple logical files may
-- reference it, so deleting either upload cannot orphan the other file's index.
CREATE TABLE IF NOT EXISTS rag_contents (
  id           text PRIMARY KEY,
  workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  content_hash text NOT NULL,
  status       text NOT NULL DEFAULT 'processing' CHECK (status IN ('processing','ready')),
  -- Which model actually produced the vectors under this content, as opposed to
  -- workspaces.embedding_* which is the space the workspace is supposed to be
  -- in. They agree by construction today; recording both is what makes a
  -- disagreement detectable instead of showing up as bad search results. Null
  -- until chunks are written (status='processing', or content with no
  -- indexable passages).
  embedding_provider_slug text,
  embedding_model_slug    text,
  embedding_model_version int,
  embedding_dim           int,
  -- Pre-parse identity of the source bytes, plus the pipeline that turned
  -- those bytes into chunk text. A later ingest of the same pair copies this
  -- row's descendants into its own workspace instead of re-parsing.
  source_sha256      text,
  pipeline_identity  text,
  -- The ingest job holding a status='processing' claim, null once ready. Other
  -- files in the workspace with the same content_hash attach to this row and
  -- wait on it, so the claim needs an owner: only the owner may keep it alive
  -- (heartbeat) and only the owner's death may drop it (lease reaper).
  claim_job_id       text,
  updated_at         timestamptz NOT NULL DEFAULT now(),
  UNIQUE (workspace_id, content_hash),
  UNIQUE (id, workspace_id)
);
CREATE INDEX IF NOT EXISTS rag_contents_donor_idx
  ON rag_contents (source_sha256, pipeline_identity)
  WHERE status = 'ready';
-- Drives the heartbeat refresh and the reaper's claim drop, both of which run
-- on every worker poll.
CREATE INDEX IF NOT EXISTS rag_contents_claim_idx
  ON rag_contents (claim_job_id)
  WHERE status = 'processing';

CREATE TABLE IF NOT EXISTS rag_file_contents (
  file_id      text PRIMARY KEY,
  workspace_id text NOT NULL,
  content_id   text NOT NULL,
  FOREIGN KEY (file_id, workspace_id)
    REFERENCES files(id, workspace_id) ON DELETE CASCADE,
  FOREIGN KEY (content_id, workspace_id)
    REFERENCES rag_contents(id, workspace_id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS rag_file_contents_content_idx ON rag_file_contents(content_id);

-- One retrievable passage. `text` is what a citation shows and what the model
-- reads; `indexed_text` is prefixed with structural headings but not a logical
-- file name, because the same content may be visible through several files.
CREATE TABLE IF NOT EXISTS rag_chunks (
  id           text PRIMARY KEY,
  workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  content_id   text NOT NULL REFERENCES rag_contents(id) ON DELETE CASCADE,
  chunk_idx    int  NOT NULL,
  -- Heading breadcrumb, e.g. 'Chapter 4 › Light reactions'. Empty for formats
  -- without headings.
  section_path text NOT NULL DEFAULT '',
  text         text NOT NULL,
  indexed_text text NOT NULL,
  token_count  int  NOT NULL DEFAULT 0,
  -- 1-based, null for sources with no page model (txt/md, parseMode=normal).
  page_start   int,
  page_end     int,
  -- [{page, bbox: [x0,y0,x1,y1], space}] for every source block in the chunk.
  -- `space` records the coordinate convention so a later highlight overlay does
  -- not have to guess; parser blocks use 'page-1000-topleft'.
  regions      jsonb NOT NULL DEFAULT '[]'::jsonb,
  -- Detected per chunk by the pipeline (lang.detect_lang): en fr de es zh ja
  -- ko, or 'und'. Names the text-search configuration `search` was built
  -- with, so a query is parsed with the same configuration when matched
  -- against this row.
  lang         text NOT NULL,
  -- Written by the pipeline, not generated: the tokenizer bigrams CJK runs so
  -- one column serves mixed-language corpora, which no built-in text search
  -- configuration can do.
  search       tsvector,
  UNIQUE (content_id, chunk_idx)
);
CREATE INDEX IF NOT EXISTS rag_chunks_ws_idx ON rag_chunks(workspace_id);
CREATE INDEX IF NOT EXISTS rag_chunks_content_idx ON rag_chunks(content_id);
CREATE INDEX IF NOT EXISTS rag_chunks_search_idx ON rag_chunks USING gin(search);

-- Vectors live beside the passage, one table per embedding width, because the
-- width is part of the column type and pgvector cannot index a column whose
-- dimension varies. Splitting only the vector keeps the lexical half of hybrid
-- search (text, indexed_text, search, regions, pages) in one place — none of it
-- depends on the embedding model.
--
-- Each embedding (provider_slug, model_slug, version) owns its own vector table. Same width
-- from another model is a different space and must not share an HNSW index.
-- rag_chunk_vectors_2560 is the historical name for qwen-embed v1; a later
-- model gets rag_chunk_vectors_<key>_<version>, even at 2560-d.
--
-- Adding a model means a new table here, a new allowlist entry in
-- pipeline/pipeline/retrieval/store.py and
-- server/internal/embeddingpins/allowlist.go,
-- and the table name listed on that catalog row's params.vector_table.
-- Removing a table is not supported: there is no reindex job
-- (see openwiki/agentic-retrieval.md).
CREATE TABLE IF NOT EXISTS rag_chunk_vectors_2560 (
  chunk_id     text PRIMARY KEY REFERENCES rag_chunks(id) ON DELETE CASCADE,
  -- Denormalized from the chunk so the vector scan can filter by workspace
  -- without joining, which is what the hybrid search CTE does.
  workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  -- halfvec because 2560 dims (Qwen3-Embedding-4B) exceeds pgvector's 2000-dim
  -- ceiling for plain vector HNSW. The pipeline hard-fails on a dimension
  -- mismatch rather than letting a short vector reach Postgres.
  embedding    halfvec(2560) NOT NULL
);
CREATE INDEX IF NOT EXISTS rag_chunk_vectors_2560_ws_idx
  ON rag_chunk_vectors_2560(workspace_id);
CREATE INDEX IF NOT EXISTS rag_chunk_vectors_2560_embedding_idx
  ON rag_chunk_vectors_2560 USING hnsw (embedding halfvec_cosine_ops);

-- Descriptor + detailed summary belong to canonical content, so duplicate
-- logical files share the model output while retaining independent file
-- lifecycles. summary_version is not part of pipeline_identity: a prompt
-- change must not invalidate a parse, but donors copy the version so a later
-- backfill can tell old prose from new.
CREATE TABLE IF NOT EXISTS rag_content_summaries (
  content_id      text PRIMARY KEY REFERENCES rag_contents(id) ON DELETE CASCADE,
  workspace_id    text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  fingerprint     text NOT NULL DEFAULT '',
  descriptor      text NOT NULL DEFAULT '',
  summary         text NOT NULL DEFAULT '',
  summary_version int  NOT NULL DEFAULT 1,
  updated_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS rag_content_summaries_ws_idx ON rag_content_summaries(workspace_id);

-- One row per search_workspace call, written when the chat turn ends so the
-- row can say which hits the answer cited. Features and ids only: no query
-- text, no passage text. The arrays are position-aligned over the hits in the
-- order the model saw them. This is what tells us whether a ranking change
-- helped (cited rate of the hits it added) without labelled data, and whether
-- the lexical leg is alive for a language (lex_ranks all null). Pruned after
-- 90 days by the writer.
CREATE TABLE IF NOT EXISTS rag_search_events (
  id            bigserial PRIMARY KEY,
  created_at    timestamptz NOT NULL DEFAULT now(),
  trace_id      text NOT NULL DEFAULT '',
  workspace_id  text REFERENCES workspaces(id) ON DELETE SET NULL,
  actor_user_id text REFERENCES users(id) ON DELETE CASCADE,
  -- Assistant message of the turn; groups the turn's searches.
  message_id    text NOT NULL DEFAULT '',
  -- 1-based position of this search among the turn's search_workspace calls.
  search_index  int  NOT NULL,
  -- Majority language of the hits. A short question rarely carries enough
  -- function words to detect its own language; what came back is the better
  -- label for "which language was this search in".
  hits_lang     text NOT NULL,
  query_terms   int  NOT NULL,
  cjk_runs      int  NOT NULL,
  scope_files   int  NOT NULL,
  embed_ms      int  NOT NULL,
  sql_ms        int  NOT NULL,
  hits          int  NOT NULL,
  -- Hits the model had already been shown earlier in the same turn.
  prior_overlap int  NOT NULL,
  chunk_ids     text[]    NOT NULL,
  file_ids      text[]    NOT NULL,
  chunk_langs   text[]    NOT NULL,
  -- Null element: that leg did not have the hit among its candidates.
  vec_ranks     int[]     NOT NULL,
  lex_ranks     int[]     NOT NULL,
  vec_dists     real[]    NOT NULL,
  -- In the result only because the exact tier raised its lexical weight.
  tier_only     boolean[] NOT NULL,
  -- Referenced as [n] in the final answer.
  cited         boolean[] NOT NULL
);
CREATE INDEX IF NOT EXISTS rag_search_events_created_idx ON rag_search_events(created_at);
CREATE INDEX IF NOT EXISTS rag_search_events_ws_idx ON rag_search_events(workspace_id, created_at);

-- Canonical content exists only while at least one logical file references it.
-- File/workspace cascades therefore clean the retrieval index without a job.
CREATE OR REPLACE FUNCTION delete_unreferenced_rag_content() RETURNS trigger AS $$
BEGIN
  DELETE FROM rag_contents c
  WHERE c.id = OLD.content_id
    AND NOT EXISTS (
      SELECT 1 FROM rag_file_contents fc WHERE fc.content_id = OLD.content_id
    ) AND NOT EXISTS (SELECT 1 FROM source_refresh_candidates sc WHERE sc.content_id=OLD.content_id);
  RETURN NULL;
END $$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS rag_file_contents_delete_orphan ON rag_file_contents;
CREATE TRIGGER rag_file_contents_delete_orphan
  AFTER DELETE OR UPDATE OF content_id ON rag_file_contents
  FOR EACH ROW EXECUTE FUNCTION delete_unreferenced_rag_content();

-- ============================================================================
-- Blob layer: refcounts and the deletion outbox
-- ============================================================================

-- One row per live object in the bucket, refcounted across every table that
-- names it. The count is maintained entirely by triggers rather than by
-- application code, because references disappear through FK cascades — a
-- workspace delete, a material delete, a user purge — where no handler runs.
--
-- Deliberately no size/content_type/etag columns. They already live on the
-- referencing rows, and two rows can legitimately share one path (cloning a
-- workspace copies blob_path rather than duplicating the object), which would
-- leave this table needing a conflict policy for metadata it does not own.
--
-- Deliberately no declared foreign key from files.blob_path or
-- editor_assets.object_path either: the row here is created by the referencing
-- table's AFTER INSERT trigger, so an immediate FK check would fire before it
-- exists. The refcount triggers are the enforcement, and unlike a helper
-- function they cannot be bypassed by a new writer that forgets to call them.
CREATE TABLE IF NOT EXISTS blobs (
  object_path text PRIMARY KEY,
  ref_count   int NOT NULL CHECK (ref_count > 0),
  created_at  timestamptz NOT NULL DEFAULT now()
);

-- Platform-owned ingest cache objects, keyed by source identity rather than by
-- a file row. Office previews also have a live file-row reference while a file
-- uses them, so cache expiry cannot remove a preview that is still viewable.
CREATE TABLE IF NOT EXISTS artifact_cache (
  object_path    text PRIMARY KEY,
  kind           text NOT NULL CHECK (kind IN ('captions', 'derived_text', 'office_preview', 'parse_bundle')),
  source_sha256  text NOT NULL,
  size_bytes     bigint NOT NULL DEFAULT 0 CHECK (size_bytes >= 0),
  created_at     timestamptz NOT NULL DEFAULT now(),
  last_used_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS artifact_cache_source_idx
  ON artifact_cache(source_sha256);
CREATE INDEX IF NOT EXISTS artifact_cache_gc_idx
  ON artifact_cache(kind, last_used_at);

-- Objects whose last database reference is gone, waiting for the reaper to
-- delete them from B2. Durable, so a failed or crashed delete is retried
-- instead of silently leaking bytes that keep being billed.
CREATE TABLE IF NOT EXISTS pending_blob_deletions (
  object_path text PRIMARY KEY,
  -- Upload paths are queued with a delay: a presigned PUT that lands after the
  -- session row is gone still has to be collected, and deleting before the URL
  -- expires would leave that late object behind forever.
  not_before  timestamptz NOT NULL DEFAULT now(),
  attempts    int NOT NULL DEFAULT 0,
  last_error  text,
  claim_token text,
  claim_expires_at timestamptz,
  created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS pending_blob_deletions_due_idx
  ON pending_blob_deletions(not_before);

-- ============================================================================
-- Direct browser-to-B2 uploads and editor media assets
-- ============================================================================

-- Editor media stored directly in Backblaze B2. The browser uploads to a
-- short-lived, server-reserved object URL. Plate documents persist only the
-- stable editor_assets.id; read URLs are resolved on demand after authorization
-- against the owning workspace or standalone material. Browser uploads are
-- workspace-scoped. A standalone asset is created only while cloning a
-- material and shares the source object's refcounted blob path.
CREATE TABLE IF NOT EXISTS editor_assets (
  id           text PRIMARY KEY,
  workspace_id text REFERENCES workspaces(id) ON DELETE CASCADE,
  material_id  text REFERENCES materials(id) ON DELETE CASCADE,
  user_id      text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_by   text REFERENCES users(id) ON DELETE SET NULL,
  name         text NOT NULL CHECK (length(name) BETWEEN 1 AND 255),
  purpose      text NOT NULL CHECK (purpose IN ('image','audio','pdf','file')),
  object_path  text NOT NULL,
  content_type text NOT NULL,
  size_bytes   bigint NOT NULL CHECK (size_bytes > 0),
  -- No 'expired' state: an abandoned reservation deletes this row so the
  -- refcount trigger can release its object. A row that stays behind holding a
  -- reference would make its object uncollectable.
  status       text NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending','ready')),
  etag         text,
  created_at   timestamptz NOT NULL DEFAULT now(),
  completed_at timestamptz,
  UNIQUE (id, workspace_id),
  CONSTRAINT editor_assets_exactly_one_owner_check CHECK (
    (workspace_id IS NOT NULL) <> (material_id IS NOT NULL)
  ),
  CHECK (
    (purpose='image' AND size_bytes <= 20971520) OR
    (purpose='audio' AND size_bytes <= 104857600) OR
    (purpose='pdf' AND size_bytes <= 52428800) OR
    (purpose='file' AND size_bytes <= 104857600)
  ),
  CHECK ((status='ready') = (completed_at IS NOT NULL))
);
CREATE INDEX IF NOT EXISTS editor_assets_workspace_idx
  ON editor_assets(workspace_id, status);
CREATE INDEX IF NOT EXISTS editor_assets_material_idx
  ON editor_assets(material_id, status);

-- Authored shared source state is separate from the last published file/index.
CREATE TABLE IF NOT EXISTS source_documents (
  user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  file_id text PRIMARY KEY REFERENCES files(id) ON DELETE CASCADE,
  format text NOT NULL CHECK (format IN ('docx','xlsx','pptx','text')),
  epoch bigint NOT NULL DEFAULT 1 CHECK (epoch > 0),
  checkpoint bigint NOT NULL DEFAULT 0 CHECK (checkpoint >= 0),
  indexed_checkpoint bigint NOT NULL DEFAULT 0 CHECK (indexed_checkpoint >= 0 AND indexed_checkpoint <= checkpoint),
  base_revision bigint NOT NULL CHECK (base_revision > 0),
  base_blob_path text NOT NULL,
  base_source_sha256 text NOT NULL DEFAULT '',
  state bytea NOT NULL DEFAULT '',
  indexed_state bytea NOT NULL DEFAULT '',
  pending_effects jsonb NOT NULL DEFAULT '[]' CHECK (jsonb_typeof(pending_effects)='array'),
  storage_bytes bigint GENERATED ALWAYS AS (octet_length(state)::bigint+octet_length(indexed_state)+octet_length(pending_effects::text)) STORED,
  net_tokens bigint NOT NULL DEFAULT 0 CHECK (net_tokens >= 0),
  last_edited_at timestamptz NOT NULL DEFAULT now(),
  last_refresh_requested_at timestamptz NOT NULL DEFAULT now(),
  desired_checkpoint bigint,
  desired_manual boolean NOT NULL DEFAULT false,
  running_job_id text REFERENCES jobs(id) ON DELETE SET NULL,
  refresh_error text,
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS source_documents_pending_idx ON source_documents(last_edited_at)
  WHERE checkpoint > indexed_checkpoint;

-- One fixed in-flight export. A newer desired checkpoint remains on the room.
CREATE TABLE IF NOT EXISTS source_refresh_candidates (
  user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  file_id text PRIMARY KEY REFERENCES source_documents(file_id) ON DELETE CASCADE,
  job_id text NOT NULL UNIQUE REFERENCES jobs(id) ON DELETE CASCADE,
  epoch bigint NOT NULL,
  checkpoint bigint NOT NULL,
  lease_token text NOT NULL,
  state bytea NOT NULL,
  source_blob_path text,
  source_sha256 text,
  size_bytes bigint NOT NULL DEFAULT 0 CHECK (size_bytes >= 0),
  seed bytea,
  preview_blob_path text,
  parse_artifact_key text,
  parse_artifact_fingerprint text,
  parse_artifact_version text,
  content_id text REFERENCES rag_contents(id) ON DELETE SET NULL,
  content_hash text,
  image_sha256s text[] NOT NULL DEFAULT '{}',
  storage_bytes bigint GENERATED ALWAYS AS (octet_length(state)::bigint+COALESCE(octet_length(seed),0)+size_bytes) STORED,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TRIGGER source_refresh_candidate_content_cleanup
AFTER DELETE OR UPDATE OF content_id ON source_refresh_candidates
FOR EACH ROW EXECUTE FUNCTION delete_unreferenced_rag_content();

CREATE TABLE IF NOT EXISTS pdf_annotations (
  id text PRIMARY KEY,
  file_id text NOT NULL REFERENCES files(id) ON DELETE CASCADE,
  author_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  source_identity text NOT NULL,
  page integer NOT NULL CHECK (page > 0),
  kind text NOT NULL CHECK (kind IN ('highlight','rectangle','ellipse')),
  rects jsonb NOT NULL CHECK (jsonb_typeof(rects)='array' AND jsonb_array_length(rects) BETWEEN 1 AND 1000),
  color text NOT NULL CHECK (color ~ '^#[0-9a-fA-F]{6}$'),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS pdf_annotations_author_file_idx ON pdf_annotations(author_id,file_id,source_identity,page);

-- Resource ownership, never an image hash alone, authorizes caption reuse.
CREATE TABLE IF NOT EXISTS image_caption_associations (
  id text PRIMARY KEY,
  file_id text REFERENCES files(id) ON DELETE CASCADE,
  editor_asset_id text REFERENCES editor_assets(id) ON DELETE CASCADE,
  image_sha256 text NOT NULL CHECK (image_sha256 ~ '^[0-9a-f]{64}$'),
  caption_blob_path text NOT NULL,
  published boolean NOT NULL DEFAULT true,
  size_bytes bigint NOT NULL CHECK (size_bytes >= 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK ((file_id IS NOT NULL) <> (editor_asset_id IS NOT NULL)),
  UNIQUE (file_id,image_sha256),
  UNIQUE (editor_asset_id,image_sha256)
);
CREATE INDEX IF NOT EXISTS image_caption_associations_sha_idx ON image_caption_associations(image_sha256);

-- One reservation table for both upload flows. They were separate tables with
-- ~90% identical columns, one shared reservation trigger and two near-duplicate
-- sweepers; target discriminates instead. The destinations stay separate
-- tables, because files and editor_assets diverge in both columns and query
-- patterns, and a single wide table risks an editor asset leaking into the file
-- tree or the RAG ingest scope.
CREATE TABLE IF NOT EXISTS upload_sessions (
  id            text PRIMARY KEY,
  target        text NOT NULL DEFAULT 'source'
    CHECK (target IN ('source','source_replace','editor_asset')),
  workspace_id  text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  -- Storage owner (the workspace owner), which is who the reservation is
  -- charged to. created_by is the uploader, carried onto files.created_by when
  -- the session finalizes.
  user_id       text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_by    text REFERENCES users(id) ON DELETE SET NULL,
  -- object_path is where the browser PUTs; final_path is where the object is
  -- promoted to on completion. Neither is unique-per-target, so both
  -- constraints stay table-wide.
  object_path   text NOT NULL UNIQUE,
  final_path    text NOT NULL UNIQUE,
  content_type  text NOT NULL DEFAULT 'application/octet-stream',
  declared_size bigint NOT NULL CHECK (declared_size >= 0),
  -- New uploads reserve their full size. Replacements reserve only positive
  -- growth because the current file is already charged to the same owner.
  reserved_size bigint CHECK (reserved_size >= 0),
  status        text NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending','completed','expired')),
  -- Source-only: the file tree placement and parser selection.
  chapter_id    text,
  chapter_name  text NOT NULL DEFAULT '',
  name          text NOT NULL DEFAULT '',
  kind          text NOT NULL DEFAULT '',
  parse_mode    text NOT NULL DEFAULT '',
  -- Whether the ingest worker should describe the figures this parse extracts.
  -- Chosen per file at reservation time and copied onto the ingest job, because
  -- the choice changes the indexed text and therefore the content hash.
  caption_images boolean NOT NULL DEFAULT false,
  source_etag   text,
  file_id       text REFERENCES files(id) ON DELETE CASCADE,
  expected_revision bigint CHECK (expected_revision > 0),
  -- Editor-asset-only: the pending row in editor_assets this fills in.
  asset_id      text,
  created_at    timestamptz NOT NULL DEFAULT now(),
  expires_at    timestamptz NOT NULL,
  completed_at  timestamptz,
  FOREIGN KEY (chapter_id, workspace_id)
    REFERENCES chapters(id, workspace_id) ON DELETE SET NULL (chapter_id),
  -- Deleting the asset row takes its reservation with it, which is what keeps
  -- the reserved-bytes counter correct through a workspace cascade.
  FOREIGN KEY (asset_id, workspace_id)
    REFERENCES editor_assets(id, workspace_id) ON DELETE CASCADE,
  CONSTRAINT upload_sessions_source_fields CHECK (
    target NOT IN ('source','source_replace') OR
      (name <> '' AND kind <> '' AND parse_mode <> '')
  ),
  CONSTRAINT upload_sessions_asset_fields CHECK (
    (target = 'editor_asset') = (asset_id IS NOT NULL)
  ),
  CONSTRAINT upload_sessions_file_target CHECK (
    file_id IS NULL OR target IN ('source','source_replace')
  ),
  CONSTRAINT upload_sessions_replace_fields CHECK (
    (target = 'source_replace') =
      (file_id IS NOT NULL AND expected_revision IS NOT NULL)
  )
);
CREATE INDEX IF NOT EXISTS upload_sessions_expiry_idx
  ON upload_sessions(status, expires_at);
-- Completing an editor-asset upload looks the session up by asset; one live
-- reservation per asset.
CREATE UNIQUE INDEX IF NOT EXISTS upload_sessions_asset_uidx
  ON upload_sessions(asset_id) WHERE asset_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS upload_sessions_replace_file_idx
  ON upload_sessions(file_id, status) WHERE target='source_replace';

-- Drive/OneDrive import state is deliberately separate from upload_sessions.
-- The upload row owns quota and object finalization; this row carries the
-- provider reference plus the attempt lease the pipeline's `import` job fences
-- its callbacks with. Queueing and retry live on the matching `jobs` row.
CREATE TABLE IF NOT EXISTS source_import_requests (
  actor_user_id  text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  request_id     text NOT NULL,
  workspace_id   text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  fingerprint    text NOT NULL,
  response       jsonb,
  created_at     timestamptz NOT NULL DEFAULT now(),
  completed_at   timestamptz,
  PRIMARY KEY (actor_user_id, request_id),
  CHECK ((response IS NOT NULL) = (completed_at IS NOT NULL))
);

CREATE TABLE IF NOT EXISTS source_import_jobs (
  id                 text PRIMARY KEY,
  upload_session_id  text NOT NULL UNIQUE
    REFERENCES upload_sessions(id) ON DELETE CASCADE,
  actor_user_id      text REFERENCES users(id) ON DELETE SET NULL,
  provider           text NOT NULL CHECK (provider IN ('google','microsoft')),
  provider_file_id   text NOT NULL,
  provider_drive_id  text NOT NULL DEFAULT '',
  max_bytes          bigint NOT NULL CHECK (max_bytes > 0),
  idempotency_key    text NOT NULL,
  trace_id           text NOT NULL DEFAULT '',
  status             text NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending','running','succeeded','failed','cancelled')),
  attempts           integer NOT NULL DEFAULT 0 CHECK (attempts >= 0),
  lease_token        text,
  lease_expires_at   timestamptz,
  attempt_object_path text,
  last_error_code    text,
  last_error         text,
  created_at         timestamptz NOT NULL DEFAULT now(),
  updated_at         timestamptz NOT NULL DEFAULT now(),
  completed_at       timestamptz,
  CHECK ((status = 'running') = (lease_token IS NOT NULL)),
  CHECK ((status = 'running') = (lease_expires_at IS NOT NULL)),
  CHECK ((status = 'running') = (attempt_object_path IS NOT NULL)),
  CHECK ((status IN ('succeeded','failed','cancelled')) =
    (completed_at IS NOT NULL)),
  UNIQUE (actor_user_id, idempotency_key)
);

-- ============================================================================
-- Logical storage accounting
-- ============================================================================

-- The counter is deliberately separate from users. Material saves append to
-- user_storage_deltas instead of taking this row lock; creation gates fold the
-- pending deltas into their read before deciding whether to allow a write.
CREATE TABLE IF NOT EXISTS user_storage (
  user_id        text PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  used_bytes     bigint NOT NULL DEFAULT 0,
  reserved_bytes bigint NOT NULL DEFAULT 0,
  updated_at     timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS user_storage_deltas (
  id         bigserial PRIMARY KEY,
  user_id    text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  delta_bytes bigint NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS user_storage_deltas_user_idx
  ON user_storage_deltas(user_id, id);

CREATE OR REPLACE FUNCTION ensure_user_storage_row(p_user_id text)
RETURNS void
LANGUAGE plpgsql
AS $$
BEGIN
  IF p_user_id IS NULL OR p_user_id = '' THEN
    RAISE EXCEPTION 'storage owner is required';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM users WHERE id = p_user_id) THEN
    RETURN;
  END IF;
  INSERT INTO user_storage (user_id)
  VALUES (p_user_id)
  ON CONFLICT (user_id) DO NOTHING;
END;
$$;

CREATE OR REPLACE FUNCTION adjust_user_storage_used(p_user_id text, p_delta bigint)
RETURNS void
LANGUAGE plpgsql
AS $$
BEGIN
  PERFORM ensure_user_storage_row(p_user_id);
  UPDATE user_storage
  SET used_bytes = GREATEST(0, used_bytes + p_delta),
      updated_at = now()
  WHERE user_id = p_user_id;
END;
$$;

CREATE OR REPLACE FUNCTION adjust_user_storage_reserved(p_user_id text, p_delta bigint)
RETURNS void
LANGUAGE plpgsql
AS $$
BEGIN
  PERFORM ensure_user_storage_row(p_user_id);
  UPDATE user_storage
  SET reserved_bytes = GREATEST(0, reserved_bytes + p_delta),
      updated_at = now()
  WHERE user_id = p_user_id;
END;
$$;

CREATE OR REPLACE FUNCTION append_user_storage_delta(p_user_id text, p_delta bigint)
RETURNS void
LANGUAGE plpgsql
AS $$
BEGIN
  IF p_delta = 0 THEN
    RETURN;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM users WHERE id = p_user_id) THEN
    RETURN;
  END IF;
  PERFORM ensure_user_storage_row(p_user_id);
  INSERT INTO user_storage_deltas (user_id, delta_bytes)
  VALUES (p_user_id, p_delta);
END;
$$;

-- ============================================================================
-- Resource metering (inference, document parsing, egress, mail)
-- ============================================================================
--
-- The second budget. Storage above is billed to the workspace owner because
-- the bytes sit in their account; everything here is billed to the *actor* who
-- asked for the work, because the cost is the request itself and it is gone
-- whether or not anything was kept. An editor generating into someone else's
-- workspace spends their own credits and the owner's disk. Every inference
-- surface is actor-billed.

-- ============================================================================
-- Model registry
--
-- Immutable versioned rows so a pinned conversation or ingest job can always
-- resolve the exact config it started with. Platform API keys stay in env,
-- looked up by provider_slug. User-supplied keys live in
-- user_llm_credentials, never here.
-- ============================================================================

-- LLM rows (chat/generate/editor/quiz/ingest) must list thinking levels
-- from the product set. Instant is "no thinking". Retrieval and captioning
-- rows omit thinking. DeepInfra is only legal for the seeded embed hop.
CREATE OR REPLACE FUNCTION model_configs_thinking_ok(
  slots text[],
  thinking_levels text[],
  default_thinking text
)
RETURNS boolean
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
  item text;
  has_llm boolean;
BEGIN
  has_llm := slots && ARRAY['chat','generate','editor','quiz','ingest']::text[];
  IF NOT has_llm THEN
    RETURN thinking_levels = '{}' AND default_thinking = '';
  END IF;
  IF thinking_levels = '{}' OR default_thinking IS NULL OR default_thinking = '' THEN
    RETURN FALSE;
  END IF;
  IF NOT (default_thinking = ANY(thinking_levels)) THEN
    RETURN FALSE;
  END IF;
  IF 'editor' = ANY(slots) AND NOT ('instant' = ANY(thinking_levels)) THEN
    RETURN FALSE;
  END IF;
  FOREACH item IN ARRAY thinking_levels
  LOOP
    IF item NOT IN ('instant', 'low', 'mid', 'high', 'max') THEN
      RETURN FALSE;
    END IF;
  END LOOP;
  RETURN TRUE;
END;
$$;

CREATE TABLE IF NOT EXISTS model_configs (
  version                      int  NOT NULL,
  provider_name                text NOT NULL,
  model_name                   text NOT NULL,
  provider_slug                text NOT NULL,
  -- Upstream id sent to the provider. Together with provider_slug this is the
  -- model identity; version pins one immutable catalog configuration.
  model_slug                   text NOT NULL,
  -- platform_enabled: env key. byok_enabled: the actor's credential.
  -- Both on: env unless this user has a credential for provider_slug.
  platform_enabled             boolean NOT NULL DEFAULT false,
  byok_enabled                 boolean NOT NULL DEFAULT false,
  -- Tokens the product may pack into a request. Required on every
  -- chat/generate/editor/quiz/ingest row. Unused (0) on retrieval/captioning.
  context_window_tokens        int  NOT NULL,
  thinking_levels              text[] NOT NULL DEFAULT '{}',
  default_thinking             text NOT NULL DEFAULT '',
  params                       jsonb NOT NULL DEFAULT '{}'::jsonb,
  -- Slots this row may serve. A slot is a named place the product calls a
  -- model; what each slot requires of the row is the Go map in
  -- server/internal/models/slot.go, checked on every registry save.
  slots                        text[] NOT NULL,
  -- Operator-set capabilities of the model. agentic_loop is derived from the
  -- checked-in certification file and is never stored here.
  capabilities                 text[] NOT NULL DEFAULT '{}',
  -- Credit multipliers, in millionths of a credit per token. 1000 output
  -- micros is the 1x reference (one credit per 1k output tokens of Flash).
  micros_per_input_token       bigint NOT NULL,
  micros_per_output_token      bigint NOT NULL,
  -- Cache-read credit rate. Never DEFAULT 0: that would make platform
  -- cache hits free.
  micros_per_cached_input_token bigint NOT NULL,
  -- Chat/generate/editor/quiz/ingest/captioning may flip this to retire a version.
  -- Retrieval rows may not: protect_embedding_model_configs refuses
  -- enabled=false, DELETE, stripping or adding the retrieval slot, and
  -- in-place changes to the pin, model_slug, or params. Same width
  -- is a different space; a new model is a new row.
  enabled                      boolean NOT NULL DEFAULT true,
  is_default_for               text[] NOT NULL DEFAULT '{}',
  created_at                   timestamptz NOT NULL DEFAULT now(),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   text NOT NULL DEFAULT '',
  updated_by                   text NOT NULL DEFAULT '',
  PRIMARY KEY (provider_slug, model_slug, version),
  CONSTRAINT model_configs_slug_check CHECK (
    provider_slug <> '' AND model_slug <> ''
  ),
  CONSTRAINT model_configs_slots_check CHECK (
    slots <@ ARRAY['chat','generate','editor','quiz','ingest','retrieval','captioning']::text[]
    AND slots <> '{}'
  ),
  CONSTRAINT model_configs_capabilities_check CHECK (
    capabilities <@ ARRAY['vision','pdf','embedding']::text[]
  ),
  CONSTRAINT model_configs_default_for_check CHECK (
    is_default_for <@ ARRAY['chat','generate','editor','quiz','ingest','retrieval','captioning']::text[]
  ),
  CONSTRAINT model_configs_embedding_dim_check CHECK (
    NOT ('retrieval' = ANY(slots))
    OR params->>'dimensions' IN ('2560')
  ),
  CONSTRAINT model_configs_embedding_enabled_check CHECK (
    NOT ('retrieval' = ANY(slots)) OR enabled
  ),
  CONSTRAINT model_configs_enabled_path_check CHECK (
    NOT enabled OR platform_enabled OR byok_enabled
  ),
  CONSTRAINT model_configs_byok_only_no_default CHECK (
    platform_enabled OR is_default_for = '{}'
  ),
  CONSTRAINT model_configs_llm_window_check CHECK (
    NOT (slots && ARRAY['chat','generate','editor','quiz','ingest']::text[])
    OR context_window_tokens > 0
  ),
  -- Credit micros may be 0 only on BYOK-only rows. Platform chat/generate/
  -- editor/quiz/ingest/captioning need both sides > 0. Retrieval needs
  -- input > 0; output may be 0.
  CONSTRAINT model_configs_credit_rates_check CHECK (
    NOT platform_enabled
    OR (
      'retrieval' = ANY(slots)
      AND micros_per_input_token > 0
      AND micros_per_cached_input_token >= 0
      AND micros_per_output_token >= 0
    )
    OR (
      NOT ('retrieval' = ANY(slots))
      AND micros_per_input_token > 0
      AND micros_per_cached_input_token > 0
      AND micros_per_output_token > 0
    )
  ),
  CONSTRAINT model_configs_thinking_check CHECK (
    model_configs_thinking_ok(slots, thinking_levels, default_thinking)
  ),
  CONSTRAINT model_configs_embedding_table_check CHECK (
    NOT ('retrieval' = ANY(slots))
    OR params->>'vector_table' ~ '^rag_chunk_vectors_[a-z0-9_]+$'
  ),
  -- DeepInfra is only the seeded qwen-embed hop. No other router rows.
  CONSTRAINT model_configs_deepinfra_embed_check CHECK (
    provider_slug <> 'deepinfra'
    OR (
      model_slug = 'Qwen/Qwen3-Embedding-4B'
      AND slots = ARRAY['retrieval']::text[]
      AND NOT byok_enabled
    )
  )
);

-- Embedding pins live on the workspace for life. Disable, delete, stripping
-- the slot, or rewriting the model identity would leave those workspaces
-- resolving a row the operator thought had moved, or fail closed on every
-- search and upload. A new embedding model, including another 2560-d one,
-- is an INSERT. Every row's provider/model/version identity is immutable;
-- non-embedding rows can still be disabled or superseded by a new version.
CREATE OR REPLACE FUNCTION protect_embedding_model_configs() RETURNS trigger AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF 'retrieval' = ANY(OLD.slots) THEN
      RAISE EXCEPTION 'retrieval model_configs rows cannot be deleted';
    END IF;
    RETURN OLD;
  END IF;

  IF 'retrieval' = ANY(NEW.slots) AND NOT NEW.enabled THEN
    RAISE EXCEPTION 'retrieval model_configs rows cannot be disabled';
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF NEW.provider_slug IS DISTINCT FROM OLD.provider_slug
       OR NEW.model_slug IS DISTINCT FROM OLD.model_slug
       OR NEW.version IS DISTINCT FROM OLD.version THEN
      RAISE EXCEPTION 'model_configs identity is immutable; insert a new row or version';
    END IF;

    IF 'retrieval' = ANY(OLD.slots)
       AND NOT ('retrieval' = ANY(NEW.slots)) THEN
      RAISE EXCEPTION 'cannot remove retrieval from model_configs.slots';
    END IF;

    IF NOT ('retrieval' = ANY(OLD.slots))
       AND 'retrieval' = ANY(NEW.slots) THEN
      RAISE EXCEPTION 'cannot add retrieval to an existing model_configs row; insert a new row';
    END IF;

    IF 'retrieval' = ANY(OLD.slots) THEN
      IF NEW.params IS DISTINCT FROM OLD.params THEN
        RAISE EXCEPTION 'cannot change params on a retrieval model_configs row';
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END $$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS model_configs_protect_embedding ON model_configs;
CREATE TRIGGER model_configs_protect_embedding
  BEFORE INSERT OR UPDATE OR DELETE ON model_configs
  FOR EACH ROW EXECUTE FUNCTION protect_embedding_model_configs();

-- One live default per slot. The registry otherwise compares version across
-- different model refs and a tie is last-row-wins on an unordered scan. Retarget by
-- clearing the old row's is_default_for, then marking the new one, in one
-- transaction, then bump model_registry_state.version.
CREATE OR REPLACE FUNCTION protect_one_default_per_slot() RETURNS trigger AS $$
DECLARE
  clash text;
BEGIN
  IF NEW.is_default_for = '{}' THEN
    RETURN NEW;
  END IF;
  SELECT s INTO clash
  FROM unnest(NEW.is_default_for) AS s
  WHERE EXISTS (
    SELECT 1 FROM model_configs c
    WHERE (c.provider_slug, c.model_slug, c.version)
      IS DISTINCT FROM (NEW.provider_slug, NEW.model_slug, NEW.version)
      AND s = ANY(c.is_default_for)
  )
  LIMIT 1;
  IF clash IS NOT NULL THEN
    RAISE EXCEPTION 'slot % already has a default; clear the other row first', clash;
  END IF;
  RETURN NEW;
END $$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS model_configs_one_default ON model_configs;
CREATE TRIGGER model_configs_one_default
  BEFORE INSERT OR UPDATE OF is_default_for ON model_configs
  FOR EACH ROW EXECUTE FUNCTION protect_one_default_per_slot();

CREATE INDEX IF NOT EXISTS model_configs_enabled_idx
  ON model_configs (provider_slug, model_slug, version DESC) WHERE enabled;

CREATE TABLE IF NOT EXISTS model_registry_state (
  id         boolean PRIMARY KEY DEFAULT true CHECK (id),
  version    bigint NOT NULL DEFAULT 0,
  updated_at timestamptz
);
INSERT INTO model_registry_state (id, version) VALUES (true, 1)
  ON CONFLICT (id) DO NOTHING;

