-- Per-user provider keys for BYOK rows. One key unlocks every catalog model
-- with that provider_slug. Ciphertext is AES-256-GCM under LLM_CREDENTIALS_KEY.
CREATE TABLE IF NOT EXISTS user_llm_credentials (
  user_id        text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  provider_slug  text NOT NULL,
  key_ciphertext bytea NOT NULL,
  key_nonce      bytea NOT NULL,
  key_last4      text NOT NULL,
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, provider_slug),
  CONSTRAINT user_llm_credentials_provider_slug_check CHECK (
    provider_slug ~ '^[a-z0-9][a-z0-9_-]{0,62}$'
  )
);
--
-- Shape mirrors storage accounting on purpose: an append-only ledger for the
-- hot path, a counter row for the gate to lock, and a reconcile pass to repair
-- drift. Analytics (PostHog) never feeds these tables — it is sampled, ad
-- blockable, and asynchronous, none of which is acceptable for something a
-- user is charged for.

-- usage_events is the source of truth for what was consumed. Append-only:
-- corrections are new rows, never updates, so a replay always reproduces the
-- same balance.
CREATE TABLE IF NOT EXISTS usage_events (
  id             bigserial PRIMARY KEY,
  -- The W3C trace id of the request that caused this. One chat turn produces
  -- several rows (embedding, agent steps, final answer) that share a trace,
  -- which is the only way to answer "what did that one question cost".
  trace_id       text,
  actor_user_id  text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  workspace_id   text REFERENCES workspaces(id) ON DELETE SET NULL,
  -- What was consumed: llm | embedding | caption | parse | email | egress.
  kind           text NOT NULL,
  -- Where the user was: chat | generate | editor | ingest | system.
  -- Same kind, different product surface.
  surface        text NOT NULL DEFAULT 'system',
  provider       text NOT NULL DEFAULT '',
  model          text NOT NULL DEFAULT '',
  thinking       text NOT NULL DEFAULT '',
  -- Catalog identity of the config that priced this row. Distinct from the
  -- observed transport provider/model. A miss here is an error at
  -- request time, never a silent fall back to the current default.
  catalog_provider_slug text NOT NULL DEFAULT '',
  catalog_model_slug    text NOT NULL DEFAULT '',
  model_version  int  NOT NULL DEFAULT 0,
  input_tokens   bigint NOT NULL DEFAULT 0,
  output_tokens  bigint NOT NULL DEFAULT 0,
  -- Non-token resources use their real unit: parsed pages, bytes, messages.
  units          bigint NOT NULL DEFAULT 0,
  unit           text NOT NULL DEFAULT '',
  -- Parse telemetry is typed so Ops does not have to interpret metadata or a
  -- generic unit column. CPU time comes from the dedicated Marker child process;
  -- elapsed time is the request's in-container parse wall time.
  parse_pages                bigint NOT NULL DEFAULT 0,
  parse_ocr_pages            bigint NOT NULL DEFAULT 0,
  parse_cpu_milliseconds     bigint NOT NULL DEFAULT 0,
  parse_elapsed_milliseconds bigint NOT NULL DEFAULT 0,
  parse_queue_milliseconds   bigint NOT NULL DEFAULT 0,
  parse_download_milliseconds bigint NOT NULL DEFAULT 0,
  parse_upload_milliseconds  bigint NOT NULL DEFAULT 0,
  parse_worker_rss_bytes     bigint NOT NULL DEFAULT 0,
  parse_worker_pss_bytes     bigint NOT NULL DEFAULT 0,
  parse_io_read_bytes        bigint NOT NULL DEFAULT 0,
  parse_io_write_bytes       bigint NOT NULL DEFAULT 0,
  -- Internal credits, in millionths, so tier allowances stay integers.
  credit_micros  bigint NOT NULL DEFAULT 0,
  -- Reservation this settles, when the spend was gated in advance.
  reservation_id text,
  -- Stable within one spend session. Callback retries reuse this id.
  provider_call_id text,
  -- Stable for post-paid work without a provider call, such as one parse job
  -- attempt. It prevents a bookkeeping retry from charging the same attempt twice.
  idempotency_key text,
  metadata       jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at     timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT usage_events_parse_values_check CHECK (
    parse_pages >= 0 AND parse_ocr_pages >= 0
    AND parse_ocr_pages <= parse_pages
    AND parse_cpu_milliseconds >= 0
    AND parse_elapsed_milliseconds >= 0
    AND parse_queue_milliseconds >= 0
    AND parse_download_milliseconds >= 0
    AND parse_upload_milliseconds >= 0
    AND parse_worker_rss_bytes >= 0
    AND parse_worker_pss_bytes >= 0
    AND parse_io_read_bytes >= 0
    AND parse_io_write_bytes >= 0
  )
);
CREATE INDEX IF NOT EXISTS usage_events_actor_idx
  ON usage_events(actor_user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS usage_events_trace_idx
  ON usage_events(trace_id) WHERE trace_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS usage_events_ops_time_kind_idx
  ON usage_events(created_at, kind);
CREATE UNIQUE INDEX IF NOT EXISTS usage_events_provider_call_idx
  ON usage_events(reservation_id, provider_call_id)
  WHERE reservation_id IS NOT NULL AND provider_call_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS usage_events_idempotency_idx
  ON usage_events(idempotency_key) WHERE idempotency_key IS NOT NULL;

-- Compact ingest-host telemetry and parser capacity analysis. The sampler
-- writes every five seconds while jobs are active and every sixty seconds when
-- idle. It deliberately carries no file, user, or document identifiers.
CREATE TABLE IF NOT EXISTS ingest_host_samples (
  sampled_at          timestamptz NOT NULL DEFAULT now(),
  environment         text NOT NULL,
  host_id             text NOT NULL,
  release_sha         text NOT NULL DEFAULT '',
  host_metrics_available boolean NOT NULL DEFAULT true,
  active_jobs         smallint NOT NULL DEFAULT 0,
  queued_jobs         smallint NOT NULL DEFAULT 0,
  active_slices       smallint NOT NULL DEFAULT 0,
  queued_slices       integer NOT NULL DEFAULT 0,
  oldest_active_slice_ms bigint NOT NULL DEFAULT 0,
  oldest_queued_slice_ms bigint NOT NULL DEFAULT 0,
  last_slice_completed_age_ms bigint NOT NULL DEFAULT 0,
  parser_oom_kill_events bigint NOT NULL DEFAULT 0,
  cpu_percent         real NOT NULL DEFAULT 0,
  load_1              real NOT NULL DEFAULT 0,
  memory_total_bytes  bigint NOT NULL DEFAULT 0,
  memory_used_bytes   bigint NOT NULL DEFAULT 0,
  memory_available_bytes bigint NOT NULL DEFAULT 0,
  swap_used_bytes     bigint NOT NULL DEFAULT 0,
  disk_read_bytes     bigint NOT NULL DEFAULT 0,
  disk_write_bytes    bigint NOT NULL DEFAULT 0,
  network_rx_bytes    bigint NOT NULL DEFAULT 0,
  network_tx_bytes    bigint NOT NULL DEFAULT 0,
  parser_memory_bytes bigint NOT NULL DEFAULT 0,
  parser_pss_bytes    bigint NOT NULL DEFAULT 0,
  parser_memory_peak_bytes bigint NOT NULL DEFAULT 0,
  parse_ready_jobs     integer NOT NULL DEFAULT 0,
  parse_delayed_jobs   integer NOT NULL DEFAULT 0,
  parse_running_jobs   integer NOT NULL DEFAULT 0,
  ingest_ready_jobs    integer NOT NULL DEFAULT 0,
  ingest_delayed_jobs  integer NOT NULL DEFAULT 0,
  ingest_running_jobs  integer NOT NULL DEFAULT 0,
  expired_leases       integer NOT NULL DEFAULT 0,
  oldest_queued_job_ms bigint NOT NULL DEFAULT 0,
  disk_free_bytes      bigint NOT NULL DEFAULT 0,
  spool_bytes          bigint NOT NULL DEFAULT 0,
  spool_files          integer NOT NULL DEFAULT 0,
  CONSTRAINT ingest_host_samples_identity UNIQUE (
    environment, host_id, sampled_at
  ),
  CONSTRAINT ingest_host_samples_values_check CHECK (
    environment <> '' AND host_id <> ''
    AND active_jobs >= 0 AND queued_jobs >= 0
    AND active_slices >= 0 AND queued_slices >= 0
    AND oldest_active_slice_ms >= 0 AND oldest_queued_slice_ms >= 0
    AND last_slice_completed_age_ms >= 0 AND parser_oom_kill_events >= 0
    AND cpu_percent >= 0 AND cpu_percent <= 100
    AND load_1 >= 0
    AND memory_total_bytes >= 0 AND memory_used_bytes >= 0
    AND memory_available_bytes >= 0 AND swap_used_bytes >= 0
    AND disk_read_bytes >= 0 AND disk_write_bytes >= 0
    AND network_rx_bytes >= 0 AND network_tx_bytes >= 0
    AND parser_memory_bytes >= 0 AND parser_pss_bytes >= 0
    AND parser_memory_peak_bytes >= 0
    AND parse_ready_jobs >= 0 AND parse_delayed_jobs >= 0
    AND parse_running_jobs >= 0 AND ingest_ready_jobs >= 0
    AND ingest_delayed_jobs >= 0 AND ingest_running_jobs >= 0
    AND expired_leases >= 0 AND oldest_queued_job_ms >= 0
    AND disk_free_bytes >= 0 AND spool_bytes >= 0 AND spool_files >= 0
  )
);
CREATE INDEX IF NOT EXISTS ingest_host_samples_sampled_brin_idx
  ON ingest_host_samples USING brin(sampled_at);

-- The sampler refreshes the current minute after every raw write. Raw rows are
-- kept for 30 days; these minute rows keep one year of capacity history.
CREATE TABLE IF NOT EXISTS ingest_host_sample_rollups (
  bucket              timestamptz NOT NULL,
  environment         text NOT NULL,
  host_id             text NOT NULL,
  release_sha         text NOT NULL DEFAULT '',
  host_metrics_available boolean NOT NULL DEFAULT true,
  samples             integer NOT NULL CHECK (samples > 0),
  active_jobs_max     integer NOT NULL DEFAULT 0,
  queued_jobs_max     integer NOT NULL DEFAULT 0,
  active_slices_max   integer NOT NULL DEFAULT 0,
  queued_slices_max   integer NOT NULL DEFAULT 0,
  oldest_active_slice_ms_max bigint NOT NULL DEFAULT 0,
  oldest_queued_slice_ms_max bigint NOT NULL DEFAULT 0,
  parser_oom_kill_events_max bigint NOT NULL DEFAULT 0,
  cpu_percent_avg     real NOT NULL DEFAULT 0,
  cpu_percent_max     real NOT NULL DEFAULT 0,
  load_1_avg          real NOT NULL DEFAULT 0,
  memory_used_bytes_avg bigint NOT NULL DEFAULT 0,
  memory_used_bytes_max bigint NOT NULL DEFAULT 0,
  memory_total_bytes_max bigint NOT NULL DEFAULT 0,
  swap_used_bytes_max bigint NOT NULL DEFAULT 0,
  parser_memory_bytes_avg bigint NOT NULL DEFAULT 0,
  parser_memory_bytes_max bigint NOT NULL DEFAULT 0,
  parser_pss_bytes_max bigint NOT NULL DEFAULT 0,
  parser_memory_peak_bytes_max bigint NOT NULL DEFAULT 0,
  parse_ready_jobs_max integer NOT NULL DEFAULT 0,
  parse_delayed_jobs_max integer NOT NULL DEFAULT 0,
  parse_running_jobs_max integer NOT NULL DEFAULT 0,
  ingest_ready_jobs_max integer NOT NULL DEFAULT 0,
  ingest_delayed_jobs_max integer NOT NULL DEFAULT 0,
  ingest_running_jobs_max integer NOT NULL DEFAULT 0,
  expired_leases_max integer NOT NULL DEFAULT 0,
  oldest_queued_job_ms_max bigint NOT NULL DEFAULT 0,
  disk_free_bytes_min bigint NOT NULL DEFAULT 0,
  spool_bytes_max bigint NOT NULL DEFAULT 0,
  spool_files_max integer NOT NULL DEFAULT 0,
  PRIMARY KEY (bucket, environment, host_id)
);
CREATE INDEX IF NOT EXISTS ingest_host_sample_rollups_bucket_brin_idx
  ON ingest_host_sample_rollups USING brin(bucket);

-- Each one-job worker reports its own cgroup. CPU is stored as cores used over
-- the interval rather than a percentage so a future worker with a wider quota
-- can exceed one core without corrupting the metric.
CREATE TABLE IF NOT EXISTS ingest_worker_samples (
  sampled_at          timestamptz NOT NULL DEFAULT now(),
  environment         text NOT NULL,
  host_id             text NOT NULL,
  worker_instance_id  text NOT NULL,
  role                text NOT NULL CHECK (role IN ('parse', 'ingest')),
  release_sha         text NOT NULL DEFAULT '',
  state               text NOT NULL CHECK (state IN ('idle', 'busy')),
  stage               text NOT NULL DEFAULT '',
  job_attempt_id      bigint REFERENCES ingest_job_attempts(id) ON DELETE SET NULL,
  cpu_cores           real NOT NULL DEFAULT 0 CHECK (cpu_cores >= 0),
  cpu_usage_usec      bigint NOT NULL DEFAULT 0 CHECK (cpu_usage_usec >= 0),
  memory_bytes        bigint NOT NULL DEFAULT 0 CHECK (memory_bytes >= 0),
  memory_peak_bytes   bigint NOT NULL DEFAULT 0 CHECK (memory_peak_bytes >= 0),
  memory_limit_bytes  bigint NOT NULL DEFAULT 0 CHECK (memory_limit_bytes >= 0),
  io_read_bytes       bigint NOT NULL DEFAULT 0 CHECK (io_read_bytes >= 0),
  io_write_bytes      bigint NOT NULL DEFAULT 0 CHECK (io_write_bytes >= 0),
  pids_current        integer NOT NULL DEFAULT 0 CHECK (pids_current >= 0),
  pids_limit          integer NOT NULL DEFAULT 0 CHECK (pids_limit >= 0),
  oom_events          bigint NOT NULL DEFAULT 0 CHECK (oom_events >= 0),
  oom_kill_events     bigint NOT NULL DEFAULT 0 CHECK (oom_kill_events >= 0),
  CONSTRAINT ingest_worker_samples_identity UNIQUE (
    environment, worker_instance_id, sampled_at
  ),
  CONSTRAINT ingest_worker_samples_identity_check CHECK (
    environment <> '' AND host_id <> '' AND worker_instance_id <> ''
  )
);
CREATE INDEX IF NOT EXISTS ingest_worker_samples_sampled_brin_idx
  ON ingest_worker_samples USING brin(sampled_at);
CREATE INDEX IF NOT EXISTS ingest_worker_samples_latest_idx
  ON ingest_worker_samples(environment, role, sampled_at DESC);

CREATE TABLE IF NOT EXISTS ingest_worker_sample_rollups (
  bucket              timestamptz NOT NULL,
  environment         text NOT NULL,
  host_id             text NOT NULL,
  worker_instance_id  text NOT NULL,
  role                text NOT NULL CHECK (role IN ('parse', 'ingest')),
  release_sha         text NOT NULL DEFAULT '',
  samples             integer NOT NULL CHECK (samples > 0),
  busy_samples        integer NOT NULL DEFAULT 0 CHECK (busy_samples >= 0),
  cpu_cores_avg       real NOT NULL DEFAULT 0,
  cpu_cores_max       real NOT NULL DEFAULT 0,
  memory_bytes_avg    bigint NOT NULL DEFAULT 0,
  memory_bytes_max    bigint NOT NULL DEFAULT 0,
  memory_peak_bytes_max bigint NOT NULL DEFAULT 0,
  memory_limit_bytes_max bigint NOT NULL DEFAULT 0,
  io_read_bytes_max   bigint NOT NULL DEFAULT 0,
  io_write_bytes_max  bigint NOT NULL DEFAULT 0,
  pids_current_max    integer NOT NULL DEFAULT 0,
  pids_limit_max      integer NOT NULL DEFAULT 0,
  oom_events_max      bigint NOT NULL DEFAULT 0,
  oom_kill_events_max bigint NOT NULL DEFAULT 0,
  PRIMARY KEY (bucket, environment, worker_instance_id)
);
CREATE INDEX IF NOT EXISTS ingest_worker_sample_rollups_bucket_brin_idx
  ON ingest_worker_sample_rollups USING brin(bucket);

-- The counter the spend gate locks. period_start makes the monthly allowance
-- reset lazily on first read of a new month rather than needing a cron that
-- must not be missed.
CREATE TABLE IF NOT EXISTS user_credits (
  user_id         text PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  period_start    date NOT NULL DEFAULT date_trunc('month', now())::date,
  used_micros     bigint NOT NULL DEFAULT 0,
  reserved_micros bigint NOT NULL DEFAULT 0,
  updated_at      timestamptz NOT NULL DEFAULT now()
);

-- A provider session groups the calls made for one request or ingest job. It
-- owns the concurrency lease and snapshots the model identity and LLM rates
-- used to settle those calls. Sweep sessions left open after a request or job
-- dies.
CREATE TABLE IF NOT EXISTS provider_sessions (
  id             text PRIMARY KEY,
  actor_user_id  text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  workspace_id   text REFERENCES workspaces(id) ON DELETE SET NULL,
  trace_id       text,
  surface        text NOT NULL DEFAULT 'system',
  reserved_micros bigint NOT NULL DEFAULT 0,
  paid_by        text NOT NULL DEFAULT 'platform'
    CHECK (paid_by IN ('platform', 'user')),
  llm_provider_slug text NOT NULL DEFAULT '',
  llm_model_slug text NOT NULL DEFAULT '',
  llm_model_version int NOT NULL DEFAULT 0,
  thinking       text NOT NULL DEFAULT '',
  llm_micros_per_input_token bigint NOT NULL DEFAULT 0,
  llm_micros_per_output_token bigint NOT NULL DEFAULT 0,
  llm_micros_per_cached_input_token bigint NOT NULL DEFAULT 0,
  embedding_provider_slug text NOT NULL DEFAULT '',
  embedding_model_slug text NOT NULL DEFAULT '',
  embedding_model_version int NOT NULL DEFAULT 0,
  credits_exhausted_at timestamptz,
  terminal_call_id text,
  status         text NOT NULL DEFAULT 'open'
    CHECK (status IN ('open', 'settled', 'released')),
  created_at     timestamptz NOT NULL DEFAULT now(),
  expires_at     timestamptz NOT NULL,
  settled_at     timestamptz
);
CREATE INDEX IF NOT EXISTS provider_sessions_open_idx
  ON provider_sessions(expires_at) WHERE status = 'open';
CREATE INDEX IF NOT EXISTS provider_sessions_actor_idx
  ON provider_sessions(actor_user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS provider_sessions_actor_open_surface_idx
  ON provider_sessions(actor_user_id, surface)
  WHERE status = 'open';

-- One outbound provider attempt. Inserted before the HTTP call (open), then
-- filled with measured tokens and applied to user_credits in the same
-- transaction (applied). Provider failures leave an abandoned stub.
CREATE TABLE IF NOT EXISTS provider_calls (
  id             text PRIMARY KEY,
  reservation_id text NOT NULL REFERENCES provider_sessions(id) ON DELETE CASCADE,
  actor_user_id  text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  job_attempt_id bigint REFERENCES ingest_job_attempts(id) ON DELETE SET NULL,
  job_stage      text NOT NULL DEFAULT '',
  kind           text NOT NULL,
  purpose        text NOT NULL DEFAULT '',
  status         text NOT NULL DEFAULT 'open'
    CHECK (status IN ('open', 'applied', 'abandoned')),
  provider       text NOT NULL DEFAULT '',
  model          text NOT NULL DEFAULT '',
  thinking       text NOT NULL DEFAULT '',
  input_tokens   bigint NOT NULL DEFAULT 0,
  output_tokens  bigint NOT NULL DEFAULT 0,
  units          bigint NOT NULL DEFAULT 0 CHECK (units >= 0),
  unit           text NOT NULL DEFAULT '',
  cached_read_tokens bigint NOT NULL DEFAULT 0,
  cache_write_tokens bigint NOT NULL DEFAULT 0,
  reasoning_tokens bigint NOT NULL DEFAULT 0,
  cache_anomaly  text NOT NULL DEFAULT '',
  -- Numeric-only context telemetry captured from the exact request shape
  -- immediately before the provider call. Providers report total input but
  -- not its composition, so these fields remain explicitly estimated.
  context_system_tokens bigint NOT NULL DEFAULT 0 CHECK (context_system_tokens >= 0),
  context_tool_tokens bigint NOT NULL DEFAULT 0 CHECK (context_tool_tokens >= 0),
  context_conversation_tokens bigint NOT NULL DEFAULT 0 CHECK (context_conversation_tokens >= 0),
  context_total_tokens bigint NOT NULL DEFAULT 0 CHECK (context_total_tokens >= 0),
  context_window_tokens bigint NOT NULL DEFAULT 0 CHECK (context_window_tokens >= 0),
  context_counting_method text NOT NULL DEFAULT '',
  context_counting_version int NOT NULL DEFAULT 0 CHECK (context_counting_version >= 0),
  credit_micros  bigint NOT NULL DEFAULT 0,
  opened_at      timestamptz NOT NULL DEFAULT now(),
  -- Closing the parent session prevents new calls but does not discard a
  -- receipt for a request already sent to the provider. Python writes a
  -- provider-timeout-specific deadline; the default covers the longest
  -- synchronous provider timeout for direct SQL and recovery callers.
  receipt_deadline_at timestamptz NOT NULL DEFAULT (now() + interval '12 hours 5 minutes'),
  received_at    timestamptz,
  applied_at     timestamptz,
  abandoned_at   timestamptz,
  error_category text NOT NULL DEFAULT '',
  error_code     text NOT NULL DEFAULT '',
  provider_status integer CHECK (
    provider_status IS NULL OR provider_status BETWEEN 100 AND 599
  ),
  CONSTRAINT provider_calls_context_total_check CHECK (
    context_total_tokens = context_system_tokens
      + context_tool_tokens + context_conversation_tokens
  ),
  CONSTRAINT provider_calls_receipt_deadline_check CHECK (
    receipt_deadline_at >= opened_at
  )
);
CREATE INDEX IF NOT EXISTS provider_calls_unbilled_idx
  ON provider_calls(opened_at)
  WHERE status = 'open';
CREATE INDEX IF NOT EXISTS provider_calls_receipt_deadline_idx
  ON provider_calls(receipt_deadline_at)
  WHERE status = 'open';
-- Ops groups every attempt by provider and model over a date range, and
-- reads the last hour's busy-abandoned attempts.
CREATE INDEX IF NOT EXISTS provider_calls_opened_idx
  ON provider_calls(opened_at);
CREATE INDEX IF NOT EXISTS provider_calls_abandoned_idx
  ON provider_calls(abandoned_at)
  WHERE status = 'abandoned';
CREATE INDEX IF NOT EXISTS provider_calls_reservation_idx
  ON provider_calls(reservation_id, kind, status, opened_at DESC);
CREATE INDEX IF NOT EXISTS provider_calls_job_attempt_idx
  ON provider_calls(job_attempt_id, opened_at)
  WHERE job_attempt_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS provider_calls_context_idx
  ON provider_calls(opened_at)
  WHERE kind = 'llm' AND context_window_tokens > 0;
CREATE INDEX IF NOT EXISTS provider_sessions_trace_idx
  ON provider_sessions(trace_id) WHERE trace_id IS NOT NULL;

-- Generic queue and history for reconciliation jobs. Scheduled and manual
-- requests enter as pending; a runner claims them with a lease. Only one run
-- of a given type executes at once, and repeated manual clicks share one
-- active manual request.
CREATE TABLE IF NOT EXISTS reconcile_runs (
  id                bigserial PRIMARY KEY,
  job_type          text NOT NULL CHECK (job_type <> ''),
  trigger           text NOT NULL CHECK (trigger IN ('scheduled', 'manual')),
  status            text NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'running', 'succeeded', 'partial', 'failed')),
  schedule_slot     timestamptz,
  requested_by_id   text REFERENCES users(id) ON DELETE SET NULL,
  requested_by_name text NOT NULL DEFAULT '',
  requested_at      timestamptz NOT NULL DEFAULT now(),
  started_at        timestamptz,
  finished_at       timestamptz,
  lease_token       text,
  lease_expires_at  timestamptz,
  attempt_count     int NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
  scanned_count     bigint NOT NULL DEFAULT 0 CHECK (scanned_count >= 0),
  repaired_count    bigint NOT NULL DEFAULT 0 CHECK (repaired_count >= 0),
  error_count       bigint NOT NULL DEFAULT 0 CHECK (error_count >= 0),
  error             text NOT NULL DEFAULT '',
  metadata          jsonb NOT NULL DEFAULT '{}'::jsonb
    CHECK (jsonb_typeof(metadata) = 'object'),
  updated_at        timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT reconcile_runs_schedule_check CHECK (
    (trigger = 'scheduled' AND schedule_slot IS NOT NULL)
    OR
    (trigger = 'manual' AND schedule_slot IS NULL)
  ),
  CONSTRAINT reconcile_runs_lease_check CHECK (
    (status = 'running' AND lease_token IS NOT NULL
      AND lease_expires_at IS NOT NULL AND started_at IS NOT NULL)
    OR
    (status <> 'running' AND lease_token IS NULL
      AND lease_expires_at IS NULL)
  )
);
CREATE UNIQUE INDEX IF NOT EXISTS reconcile_runs_running_kind_idx
  ON reconcile_runs(job_type)
  WHERE status = 'running';
CREATE UNIQUE INDEX IF NOT EXISTS reconcile_runs_active_manual_kind_idx
  ON reconcile_runs(job_type)
  WHERE status IN ('pending', 'running') AND trigger = 'manual';
CREATE UNIQUE INDEX IF NOT EXISTS reconcile_runs_schedule_idx
  ON reconcile_runs(job_type, schedule_slot)
  WHERE trigger = 'scheduled';
CREATE INDEX IF NOT EXISTS reconcile_runs_recent_idx
  ON reconcile_runs(requested_at DESC, id DESC);
CREATE INDEX IF NOT EXISTS reconcile_runs_pending_idx
  ON reconcile_runs(requested_at, id)
  WHERE status = 'pending';

-- Sparse operator inbox. Jobs write rows only for repaired drift or an item
-- that needs attention; a clean run is represented only in reconcile_runs.
CREATE TABLE IF NOT EXISTS reconciliation_report (
  id            bigserial PRIMARY KEY,
  run_id        bigint NOT NULL REFERENCES reconcile_runs(id) ON DELETE RESTRICT,
  event_type    text NOT NULL CHECK (event_type <> ''),
  subject_type  text NOT NULL CHECK (subject_type <> ''),
  subject_id    text NOT NULL CHECK (subject_id <> ''),
  actor_user_id text REFERENCES users(id) ON DELETE SET NULL,
  metadata      jsonb NOT NULL DEFAULT '{}'::jsonb
    CHECK (jsonb_typeof(metadata) = 'object'),
  created_at    timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT reconciliation_report_run_subject_unique
    UNIQUE (run_id, event_type, subject_type, subject_id)
);
CREATE INDEX IF NOT EXISTS reconciliation_report_created_idx
  ON reconciliation_report(created_at DESC);

-- Ops needs turn state and the trace that joins it to reservations and calls,
-- never message content or citation/activity metadata.
CREATE OR REPLACE VIEW ops_assistant_turns AS
SELECT m.id,
       c.user_id,
       m.status,
       NULLIF(m.metadata->>'traceId', '') AS trace_id,
       m.created_at
FROM messages m
JOIN conversations c ON c.id = m.conversation_id
WHERE m.role = 'assistant';

-- ============================================================================
-- Operator access (internal ops dashboard)
-- ============================================================================
--
-- Membership is the entire authorization model, and there is deliberately no
-- API that grants it: a row is inserted by hand against the database. An
-- escalation path reachable from the product would make every bug in the
-- product a path to everyone's data.
CREATE TABLE IF NOT EXISTS operators (
  user_id      text PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  role         text NOT NULL DEFAULT 'viewer' CHECK (role IN ('viewer', 'admin')),
  note         text NOT NULL DEFAULT '',
  created_at   timestamptz NOT NULL DEFAULT now(),
  last_seen_at timestamptz
);

-- Role-to-token map. operators.role is the grant label; endpoints check these
-- tokens, not the role name.
CREATE TABLE IF NOT EXISTS ops_permissions (
  role       text NOT NULL CHECK (role IN ('viewer', 'admin')),
  permission text NOT NULL CHECK (permission IN (
    'read_all',
    'execute_reconciliation_job',
    'write_registry'
  )),
  PRIMARY KEY (role, permission)
);
INSERT INTO ops_permissions (role, permission) VALUES
  ('viewer', 'read_all'),
  ('admin', 'read_all'),
  ('admin', 'execute_reconciliation_job'),
  ('admin', 'write_registry')
ON CONFLICT DO NOTHING;

-- One chronological record of accepted operator mutations. Domain tables
-- remain authoritative for their state and execution details; these rows hold
-- the actor, request trace, target, outcome, and a safe change summary. Actor
-- identity is intentionally not a foreign key so account deletion cannot erase
-- attribution from the audit trail.
CREATE TABLE IF NOT EXISTS operator_audit_events (
  id            bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  occurred_at   timestamptz NOT NULL DEFAULT now(),
  actor_user_id text NOT NULL CHECK (actor_user_id <> ''),
  actor_role    text NOT NULL CHECK (actor_role <> ''),
  action        text NOT NULL CHECK (action <> ''),
  target_type   text NOT NULL CHECK (target_type <> ''),
  target_id     text NOT NULL DEFAULT '',
  outcome       text NOT NULL CHECK (outcome <> ''),
  trace_id      text NOT NULL DEFAULT '',
  metadata      jsonb NOT NULL DEFAULT '{}'::jsonb
    CHECK (jsonb_typeof(metadata) = 'object')
);
CREATE INDEX IF NOT EXISTS operator_audit_events_recent_idx
  ON operator_audit_events (id DESC);
CREATE INDEX IF NOT EXISTS operator_audit_events_action_idx
  ON operator_audit_events (action, id DESC);

CREATE OR REPLACE FUNCTION reject_operator_audit_event_change()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  RAISE EXCEPTION 'operator audit events are append-only'
    USING ERRCODE = '55000';
END;
$$;
DROP TRIGGER IF EXISTS operator_audit_events_no_row_changes
  ON operator_audit_events;
CREATE TRIGGER operator_audit_events_no_row_changes
  BEFORE UPDATE OR DELETE ON operator_audit_events
  FOR EACH ROW EXECUTE FUNCTION reject_operator_audit_event_change();
DROP TRIGGER IF EXISTS operator_audit_events_no_truncate
  ON operator_audit_events;
CREATE TRIGGER operator_audit_events_no_truncate
  BEFORE TRUNCATE ON operator_audit_events
  FOR EACH STATEMENT EXECUTE FUNCTION reject_operator_audit_event_change();

CREATE OR REPLACE FUNCTION touch_operator_seen(p_user_id text)
RETURNS void
LANGUAGE sql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  UPDATE operators
     SET last_seen_at = now()
   WHERE user_id = p_user_id;
$$;
REVOKE ALL ON FUNCTION touch_operator_seen(text) FROM PUBLIC;

-- The ops actions role can request a reconciliation but cannot write the
-- queue or any business table directly. The runner owns execution.
CREATE OR REPLACE FUNCTION request_reconciliation(
  p_job_type text,
  p_user_id text,
  p_trace_id text
)
RETURNS TABLE (
  run_id bigint,
  already_queued boolean,
  requested_at timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_name text;
  v_role text;
  v_existing reconcile_runs%ROWTYPE;
BEGIN
  IF p_job_type NOT IN ('storage', 'stripe') THEN
    RAISE EXCEPTION 'unsupported reconciliation job'
      USING ERRCODE = '22023';
  END IF;

  SELECT u.name, o.role
    INTO v_name, v_role
    FROM operators o
    JOIN users u ON u.id = o.user_id
   WHERE o.user_id = p_user_id
     AND u.deleted_at IS NULL
     AND u.suspended_at IS NULL
     AND u.deletion_requested_at IS NULL
     AND EXISTS (
       SELECT 1
         FROM ops_permissions p
        WHERE p.role = o.role
          AND p.permission = 'execute_reconciliation_job'
     );
  IF NOT FOUND THEN
    RAISE EXCEPTION 'permission denied'
      USING ERRCODE = '42501';
  END IF;

  SELECT *
    INTO v_existing
    FROM reconcile_runs
   WHERE job_type = p_job_type
     AND trigger = 'manual'
     AND status IN ('pending', 'running')
   ORDER BY id
   LIMIT 1;
  IF FOUND THEN
    run_id := v_existing.id;
    already_queued := true;
    requested_at := v_existing.requested_at;
  ELSE
    BEGIN
      INSERT INTO reconcile_runs (
        job_type, trigger, status, requested_by_id, requested_by_name
      )
      VALUES (p_job_type, 'manual', 'pending', p_user_id, v_name)
      RETURNING id, false, reconcile_runs.requested_at
        INTO run_id, already_queued, requested_at;
    EXCEPTION WHEN unique_violation THEN
      SELECT id, true, reconcile_runs.requested_at
        INTO run_id, already_queued, requested_at
        FROM reconcile_runs
       WHERE job_type = p_job_type
         AND trigger = 'manual'
         AND status IN ('pending', 'running')
       ORDER BY id
       LIMIT 1;
    END;
  END IF;

  INSERT INTO operator_audit_events (
    actor_user_id, actor_role, action, target_type, target_id,
    outcome, trace_id, metadata
  ) VALUES (
    p_user_id,
    v_role,
    'reconciliation.requested',
    'reconcile_run',
    run_id::text,
    CASE WHEN already_queued THEN 'already_queued' ELSE 'queued' END,
    COALESCE(p_trace_id, ''),
    jsonb_build_object(
      'job_type', p_job_type,
      'run_id', run_id,
      'already_queued', already_queued
    )
  );
  RETURN NEXT;
END;
$$;
REVOKE ALL ON FUNCTION request_reconciliation(text, text, text) FROM PUBLIC;

-- Registry writes use ordinary table grants, so this narrow function performs
-- the second permission check and records their audit summary without granting
-- the admin-actions login direct INSERT access to the audit table.
CREATE OR REPLACE FUNCTION record_registry_audit(
  p_user_id text,
  p_previous_revision bigint,
  p_new_revision bigint,
  p_inserted_rows bigint,
  p_disabled_rows bigint,
  p_remapped_users bigint,
  p_trace_id text
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_role text;
BEGIN
  SELECT o.role
    INTO v_role
    FROM operators o
    JOIN users u ON u.id = o.user_id
   WHERE o.user_id = p_user_id
     AND u.deleted_at IS NULL
     AND u.suspended_at IS NULL
     AND u.deletion_requested_at IS NULL
     AND EXISTS (
       SELECT 1
         FROM ops_permissions p
        WHERE p.role = o.role
          AND p.permission = 'write_registry'
     );
  IF NOT FOUND THEN
    RAISE EXCEPTION 'permission denied'
      USING ERRCODE = '42501';
  END IF;

  INSERT INTO operator_audit_events (
    actor_user_id, actor_role, action, target_type, target_id,
    outcome, trace_id, metadata
  ) VALUES (
    p_user_id,
    v_role,
    'registry.saved',
    'model_registry',
    p_new_revision::text,
    'committed',
    COALESCE(p_trace_id, ''),
    jsonb_build_object(
      'previous_revision', p_previous_revision,
      'new_revision', p_new_revision,
      'inserted_rows', p_inserted_rows,
      'disabled_rows', p_disabled_rows,
      'remapped_users', p_remapped_users
    )
  );
END;
$$;
REVOKE ALL ON FUNCTION record_registry_audit(
  text, bigint, bigint, bigint, bigint, bigint, text
) FROM PUBLIC;

CREATE OR REPLACE FUNCTION save_resource_credit_rate(
  p_user_id text,
  p_resource_key text,
  p_credit_micros_per_unit bigint,
  p_trace_id text
)
RETURNS TABLE (
  resource_key text,
  version int,
  unit text,
  credit_micros_per_unit bigint,
  active boolean,
  created_at timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_role text;
  v_unit text;
  v_version int;
BEGIN
  IF p_credit_micros_per_unit < 0 THEN
    RAISE EXCEPTION 'credit rate must be non-negative' USING ERRCODE = '22023';
  END IF;
  SELECT o.role INTO v_role
  FROM operators o
  JOIN users u ON u.id = o.user_id
  WHERE o.user_id = p_user_id
    AND u.deleted_at IS NULL
    AND u.suspended_at IS NULL
    AND u.deletion_requested_at IS NULL
    AND EXISTS (
      SELECT 1 FROM ops_permissions p
      WHERE p.role = o.role AND p.permission = 'write_registry'
    );
  IF NOT FOUND THEN
    RAISE EXCEPTION 'permission denied' USING ERRCODE = '42501';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('resource-credit-rates'));
  SELECT r.unit INTO v_unit
  FROM resource_credit_rates r
  WHERE r.resource_key = p_resource_key AND r.active;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown resource rate' USING ERRCODE = '22023';
  END IF;
  SELECT COALESCE(MAX(r.version), 0) + 1 INTO v_version
  FROM resource_credit_rates r WHERE r.resource_key = p_resource_key;
  UPDATE resource_credit_rates r SET active=false
  WHERE r.resource_key = p_resource_key AND r.active;
  INSERT INTO resource_credit_rates
    (resource_key, version, unit, credit_micros_per_unit, active, created_by)
  VALUES
    (p_resource_key, v_version, v_unit, p_credit_micros_per_unit, true, p_user_id);
  INSERT INTO operator_audit_events (
    actor_user_id, actor_role, action, target_type, target_id,
    outcome, trace_id, metadata
  ) VALUES (
    p_user_id, v_role, 'resource_rate.saved', 'resource_credit_rate',
    p_resource_key, 'committed', COALESCE(p_trace_id, ''),
    jsonb_build_object(
      'version', v_version,
      'unit', v_unit,
      'credit_micros_per_unit', p_credit_micros_per_unit
    )
  );
  RETURN QUERY SELECT r.resource_key, r.version, r.unit,
    r.credit_micros_per_unit, r.active, r.created_at
  FROM resource_credit_rates r
  WHERE r.resource_key = p_resource_key AND r.version = v_version;
END;
$$;
REVOKE ALL ON FUNCTION save_resource_credit_rate(text, text, bigint, text) FROM PUBLIC;

CREATE OR REPLACE FUNCTION set_file_storage_owner()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  SELECT w.user_id INTO NEW.user_id
  FROM workspaces w
  WHERE w.id = NEW.workspace_id;
  IF NEW.user_id IS NULL THEN
    RAISE EXCEPTION 'workspace % has no storage owner', NEW.workspace_id;
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION set_upload_storage_owner()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  SELECT w.user_id INTO NEW.user_id
  FROM workspaces w
  WHERE w.id = NEW.workspace_id;
  IF NEW.user_id IS NULL THEN
    RAISE EXCEPTION 'workspace % has no storage owner', NEW.workspace_id;
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION set_editor_asset_storage_owner()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.workspace_id IS NOT NULL THEN
    SELECT w.user_id INTO NEW.user_id
    FROM workspaces w
    WHERE w.id = NEW.workspace_id;
  ELSE
    SELECT m.owner_user_id INTO NEW.user_id
    FROM materials m
    WHERE m.id = NEW.material_id AND m.workspace_id IS NULL;
  END IF;
  IF NEW.user_id IS NULL THEN
    RAISE EXCEPTION 'editor asset % has no storage owner', NEW.id;
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION prepare_material_storage_fields()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  -- Ownership is derived on insert and on a workspace move only, never from a
  -- later authorship change: created_by is nulled when an author's account is
  -- hard-deleted, and re-deriving there would both re-own the row and fail
  -- outright once the surrounding cascade has already removed the workspace.
  -- Ownership transfer therefore has to rewrite owner_user_id explicitly.
  IF TG_OP = 'INSERT' OR NEW.workspace_id IS DISTINCT FROM OLD.workspace_id THEN
    IF NEW.workspace_id IS NULL THEN
      -- Standalone material: the creator is also the storage owner.
      NEW.owner_user_id = NEW.created_by;
    ELSE
      SELECT w.user_id INTO NEW.owner_user_id
      FROM workspaces w
      WHERE w.id = NEW.workspace_id;
      -- Visibility belongs to the workspace. A copied/moved material cannot
      -- carry a standalone public/link policy into it.
      NEW.privacy = 'private';
    END IF;
    IF NEW.owner_user_id IS NULL THEN
      RAISE EXCEPTION 'material % has no storage owner', NEW.id;
    END IF;
  END IF;
  NEW.size_bytes = octet_length(NEW.content::text);
  RETURN NEW;
END;
$$;

-- ---------------------------------------------------------------------------
-- Blob refcounting
-- ---------------------------------------------------------------------------

-- blob_enqueue_deletion is the only writer of the outbox. It refuses to queue a
-- path something still points at, which is what makes it safe for the
-- upload-session trigger to queue final_path unconditionally: if the session
-- completed, the file that took the path over holds a reference.
CREATE OR REPLACE FUNCTION blob_enqueue_deletion(p_path text, p_delay interval)
RETURNS void
LANGUAGE plpgsql
AS $$
BEGIN
  IF p_path IS NULL OR p_path = '' THEN
    RETURN;
  END IF;
  -- This lock is shared with blob_ref/blob_unref and the remote reaper. It
  -- closes the gap where a transaction has started adding a reference while a
  -- reaper is deciding that the same path is unused.
  PERFORM pg_advisory_xact_lock(hashtextextended(p_path, 0));
  IF EXISTS (SELECT 1 FROM blobs WHERE object_path = p_path) THEN
    RETURN;
  END IF;
  INSERT INTO pending_blob_deletions (object_path, not_before)
  VALUES (p_path, now() + p_delay)
  ON CONFLICT (object_path) DO UPDATE
    SET not_before = greatest(pending_blob_deletions.not_before, excluded.not_before);
END;
$$;

CREATE OR REPLACE FUNCTION blob_ref(p_path text)
RETURNS void
LANGUAGE plpgsql
AS $$
DECLARE
	delete_claim text;
BEGIN
  IF p_path IS NULL OR p_path = '' THEN
    RETURN;
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_path, 0));
  -- A bucket deletion cannot be rolled back. A non-null claim means a worker
  -- may already have deleted the object, even after its lease expired. Only an
  -- explicit failed-request acknowledgement clears the token; otherwise the
  -- reaper must reclaim and retry the idempotent bucket delete.
  SELECT claim_token INTO delete_claim
  FROM pending_blob_deletions
  WHERE object_path = p_path
  FOR UPDATE;
  IF delete_claim IS NOT NULL THEN
    RAISE EXCEPTION 'blob % is being deleted; retry the transaction', p_path
      USING ERRCODE = '40001';
  END IF;

  INSERT INTO blobs (object_path, ref_count) VALUES (p_path, 1)
  ON CONFLICT (object_path) DO UPDATE SET ref_count = blobs.ref_count + 1;
  -- An unclaimed queued path can come back to life. Cancelling that queued
  -- delete stops the reaper from removing an object that is live again.
  DELETE FROM pending_blob_deletions WHERE object_path = p_path;
END;
$$;

CREATE OR REPLACE FUNCTION blob_unref(p_path text, p_delay interval)
RETURNS void
LANGUAGE plpgsql
AS $$
DECLARE
  remaining int;
BEGIN
  IF p_path IS NULL OR p_path = '' THEN
    RETURN;
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_path, 0));
  -- Decrement only while other references remain; the last one deletes the row
  -- so the CHECK (ref_count > 0) invariant holds without a zero state.
  UPDATE blobs SET ref_count = ref_count - 1
  WHERE object_path = p_path AND ref_count > 1
  RETURNING ref_count INTO remaining;
  IF remaining IS NOT NULL THEN
    RETURN;
  END IF;
  DELETE FROM blobs WHERE object_path = p_path;
  PERFORM blob_enqueue_deletion(p_path, p_delay);
END;
$$;

-- One function for every table that names blob paths. The columns arrive as
-- trigger arguments and are read through to_jsonb, so files (source blob) and
-- editor_assets (one) share it. Durable captions, derived text, Office previews,
-- and parse-bundle reuse copies are owned by artifact_cache instead, so deleting
-- one file cannot reap a cache object another upload of the same bytes still
-- wants. Local parse handoffs are governed by the shared-spool sweeper.
-- Row-level AFTER triggers fire on FK
-- cascades, which is the entire point: a workspace or user delete never runs
-- handler code, and this is what keeps the bucket in step with it.
CREATE OR REPLACE FUNCTION account_blob_refs()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  col      text;
  old_row  jsonb := CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE to_jsonb(OLD) END;
  new_row  jsonb := CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE to_jsonb(NEW) END;
  old_path text;
  new_path text;
BEGIN
  FOREACH col IN ARRAY TG_ARGV LOOP
    old_path := old_row ->> col;
    new_path := new_row ->> col;
    IF old_path IS DISTINCT FROM new_path THEN
      -- Reference before dereference, so a path moving between two rows in one
      -- statement is never briefly unreferenced and queued for deletion.
      PERFORM blob_ref(new_path);
      PERFORM blob_unref(old_path, CASE WHEN TG_TABLE_NAME='source_refresh_candidates' AND col='source_blob_path' THEN interval '1 day' ELSE interval '0' END);
    END IF;
  END LOOP;
  RETURN NULL;
END;
$$;

-- How long a vanished upload session's objects sit before the reaper takes
-- them. It has to outlast the presigned PUT URL: a request already in flight
-- can still create the object after the row is gone, and deleting early would
-- leave that object unreferenced and unqueued forever.
CREATE OR REPLACE FUNCTION account_upload_blob_deletion()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  PERFORM blob_enqueue_deletion(OLD.object_path, interval '1 day');
  PERFORM blob_enqueue_deletion(OLD.final_path, interval '1 day');
  RETURN NULL;
END;
$$;

CREATE OR REPLACE FUNCTION account_file_storage()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM adjust_user_storage_used(NEW.user_id, NEW.size_bytes);
  ELSIF TG_OP = 'DELETE' THEN
    PERFORM adjust_user_storage_used(OLD.user_id, -OLD.size_bytes);
  ELSIF OLD.user_id IS DISTINCT FROM NEW.user_id THEN
    PERFORM adjust_user_storage_used(OLD.user_id, -OLD.size_bytes);
    PERFORM adjust_user_storage_used(NEW.user_id, NEW.size_bytes);
  ELSIF OLD.size_bytes IS DISTINCT FROM NEW.size_bytes THEN
    PERFORM adjust_user_storage_used(NEW.user_id, NEW.size_bytes - OLD.size_bytes);
  END IF;
  RETURN NULL;
END;
$$;

-- Close the job, attempt, session, and reserved-credit bookkeeping selected by
-- a lifecycle boundary. An already-open provider call remains eligible for its
-- exact late receipt until receipt_deadline_at; the provider-call sweeper
-- abandons it afterward. Callers choose and lock candidates with SKIP LOCKED so
-- they never wait behind a worker that will observe the new file/account state.
CREATE OR REPLACE FUNCTION cancel_pipeline_jobs(
  target_job_ids text[],
  attempt_outcome text,
  terminal_category text,
  terminal_code text,
  terminal_detail text
)
RETURNS bigint
LANGUAGE plpgsql
AS $$
DECLARE
  cancelled_count bigint;
BEGIN
  IF attempt_outcome NOT IN ('failed', 'superseded') THEN
    RAISE EXCEPTION 'invalid pipeline cancellation outcome: %', attempt_outcome;
  END IF;
  WITH candidates AS MATERIALIZED (
    SELECT id, payload->>'reservationId' AS reservation_id
    FROM jobs
    WHERE id=ANY(COALESCE(target_job_ids, ARRAY[]::text[]))
      AND type IN ('parse','ingest','source_refresh') AND status IN ('pending','running')
    FOR UPDATE
  ), closed_attempts AS (
    UPDATE ingest_job_attempts a SET
      status=attempt_outcome, stage='cancelled', error_category=terminal_category,
      error_code=terminal_code, error_detail=terminal_detail,
      retryable=false, finished_at=COALESCE(a.finished_at, now())
    FROM candidates c
    WHERE a.job_id=c.id AND a.status='running'
    RETURNING a.id
  ), cancelled AS (
    UPDATE jobs j SET status='failed', error=terminal_detail,
      locked_at=NULL, lease_expires_at=NULL, updated_at=now()
    FROM candidates c WHERE j.id=c.id
    RETURNING c.reservation_id,j.id
  ), cleared_source AS (
    UPDATE source_documents d SET running_job_id=NULL,
      refresh_error=CASE WHEN attempt_outcome='superseded' THEN NULL ELSE terminal_detail END,
      desired_checkpoint=CASE WHEN attempt_outcome='superseded' THEN d.checkpoint ELSE d.desired_checkpoint END
    FROM cancelled j WHERE d.running_job_id=j.id
  ), discarded_source AS (
    DELETE FROM source_refresh_candidates c USING cancelled j WHERE c.job_id=j.id
  ), closed AS (
    UPDATE provider_sessions ps SET
      status=CASE WHEN EXISTS (
        SELECT 1 FROM usage_events ue WHERE ue.reservation_id=ps.id
      ) THEN 'settled' ELSE 'released' END,
      settled_at=now()
    FROM cancelled c
    WHERE ps.id=c.reservation_id AND ps.status='open'
    RETURNING ps.actor_user_id, ps.reserved_micros
  ), totals AS (
    SELECT actor_user_id, sum(reserved_micros) AS reserved_micros
    FROM closed GROUP BY actor_user_id
  ), counters AS (
    UPDATE user_credits uc SET
      reserved_micros=GREATEST(0, uc.reserved_micros-t.reserved_micros),
      updated_at=now()
    FROM totals t WHERE uc.user_id=t.actor_user_id
  )
  SELECT count(*) INTO cancelled_count FROM cancelled;
  RETURN cancelled_count;
END;
$$;

-- Deleting a file is also cancellation of every parse/ingest lease that still
-- names it. This is a database trigger because workspace/account deletion
-- reaches files through FK cascades and never calls a Go handler.
CREATE OR REPLACE FUNCTION cancel_file_pipeline_jobs()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  target_job_ids text[];
BEGIN
  SELECT COALESCE(array_agg(locked.id), ARRAY[]::text[])
  INTO target_job_ids
  FROM (
    SELECT id FROM jobs
    WHERE type IN ('parse','ingest','source_refresh')
      AND payload->>'fileId'=OLD.id
      AND status IN ('pending','running')
    FOR UPDATE SKIP LOCKED
  ) locked;
  PERFORM cancel_pipeline_jobs(
    target_job_ids, 'failed', 'lifecycle', 'source_deleted', 'source deleted'
  );
  RETURN OLD;
END;
$$;

CREATE OR REPLACE FUNCTION cancel_source_import_on_upload_delete()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  -- A running cloud import may already have staged a provider download under
  -- its attempt key. Preserve that key in the durable blob outbox before the
  -- job row is cleared; otherwise account/workspace deletion loses the only
  -- reference to imported bytes. The grace also covers an import worker upload
  -- already in flight when this cancellation commits.
  PERFORM blob_enqueue_deletion(attempt_object_path, interval '24 hours')
  FROM source_import_jobs
  WHERE upload_session_id=OLD.id
    AND status IN ('pending','running')
    AND attempt_object_path IS NOT NULL;
  UPDATE source_import_jobs SET
    status='cancelled', lease_token=NULL, lease_expires_at=NULL,
    attempt_object_path=NULL, completed_at=COALESCE(completed_at, now()),
    last_error_code='source_deleted', last_error='source deleted', updated_at=now()
  WHERE upload_session_id=OLD.id AND status IN ('pending','running');
  RETURN OLD;
END;
$$;

-- Entering account deletion is an immediate execution boundary even though
-- durable content remains recoverable for 30 days. Stop work that is billed to
-- the user, work on content they own, and imports they initiated; release every
-- open credit reservation so a locked account cannot keep consuming capacity.
-- Calls already sent remain settleable by exact id until their receipt
-- deadline; closing their sessions still prevents any new provider call.
CREATE OR REPLACE FUNCTION cancel_user_async_work(target_user_id text)
RETURNS void
LANGUAGE plpgsql
AS $$
BEGIN
  WITH candidates AS MATERIALIZED (
    SELECT j.id, j.payload->>'reservationId' AS reservation_id,
           j.payload->>'fileId' AS file_id,
           COALESCE(j.payload->>'sourceETag', '') AS source_etag,
           CASE WHEN jsonb_typeof(j.payload->'sourceRevision')='number'
                THEN (j.payload->>'sourceRevision')::bigint END AS source_revision
    FROM jobs j
    LEFT JOIN files f ON f.id=j.payload->>'fileId'
    LEFT JOIN workspaces w ON w.id=f.workspace_id
    WHERE j.type IN ('import','parse','ingest','source_refresh')
      AND j.status IN ('pending','running')
      AND (j.payload->>'actorUserId'=target_user_id OR w.user_id=target_user_id)
    FOR UPDATE OF j SKIP LOCKED
  ), closed_attempts AS (
    UPDATE ingest_job_attempts a SET
      status='failed', stage='cancelled', error_category='lifecycle',
      error_code='account_deletion', error_detail='account deletion requested',
      retryable=false, finished_at=COALESCE(a.finished_at, now())
    FROM candidates c
    WHERE a.job_id=c.id AND a.status='running'
  ), abandoned_content AS (
    DELETE FROM rag_contents rc
    USING candidates c
    WHERE rc.claim_job_id=c.id AND rc.status='processing'
  ), failed_files AS (
    UPDATE files f SET status='failed', indexed=false, preview_blob_path=NULL
    FROM candidates c
    WHERE f.id=c.file_id
      AND f.status IN ('pending','processing')
      AND (c.source_revision IS NULL OR f.revision=c.source_revision)
      AND COALESCE(f.source_etag, '')=c.source_etag
  ), cancelled AS (
    UPDATE jobs j SET status='failed', error='account deletion requested',
      locked_at=NULL, lease_expires_at=NULL, updated_at=now()
    FROM candidates c WHERE j.id=c.id
    RETURNING c.reservation_id,j.id
  ), cleared_source AS (
    UPDATE source_documents d SET running_job_id=NULL,refresh_error='account deletion requested'
    FROM cancelled j WHERE d.running_job_id=j.id
  ), discarded_source AS (
    DELETE FROM source_refresh_candidates c USING cancelled j WHERE c.job_id=j.id
  ), provider_targets AS (
    SELECT reservation_id AS id FROM cancelled WHERE reservation_id IS NOT NULL
    UNION
    SELECT id FROM provider_sessions
    WHERE actor_user_id=target_user_id AND status='open'
  ), closed AS (
    UPDATE provider_sessions ps SET
      status=CASE WHEN EXISTS (
        SELECT 1 FROM usage_events ue WHERE ue.reservation_id=ps.id
      ) THEN 'settled' ELSE 'released' END,
      settled_at=now()
    FROM provider_targets p
    WHERE ps.id=p.id AND ps.status='open'
    RETURNING ps.actor_user_id, ps.reserved_micros
  ), totals AS (
    SELECT actor_user_id, sum(reserved_micros) AS reserved_micros
    FROM closed GROUP BY actor_user_id
  )
  UPDATE user_credits uc SET
    reserved_micros=GREATEST(0, uc.reserved_micros-t.reserved_micros),
    updated_at=now()
  FROM totals t WHERE uc.user_id=t.actor_user_id;

  -- Removing unfinished upload sessions releases storage reservations and the
  -- existing delete trigger cancels/clears any cloud-import lease.
  DELETE FROM upload_sessions us
  USING workspaces w
  WHERE us.workspace_id=w.id AND us.status='pending'
    AND (
      us.created_by=target_user_id OR w.user_id=target_user_id OR EXISTS (
        SELECT 1 FROM source_import_jobs sij
        WHERE sij.upload_session_id=us.id AND sij.actor_user_id=target_user_id
      )
    );

  DELETE FROM source_import_requests WHERE actor_user_id=target_user_id;
END;
$$;

CREATE OR REPLACE FUNCTION account_material_storage()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM adjust_user_storage_used(NEW.owner_user_id, NEW.size_bytes);
  ELSIF TG_OP = 'DELETE' THEN
    -- Material edits are ledger-backed. Keep deletion in the same ledger so
    -- a pending growth delta cannot be stranded above a clamped base counter.
    PERFORM append_user_storage_delta(OLD.owner_user_id, -OLD.size_bytes);
  ELSIF OLD.owner_user_id IS DISTINCT FROM NEW.owner_user_id THEN
    PERFORM append_user_storage_delta(OLD.owner_user_id, -OLD.size_bytes);
    PERFORM append_user_storage_delta(NEW.owner_user_id, NEW.size_bytes);
  ELSIF OLD.size_bytes IS DISTINCT FROM NEW.size_bytes THEN
    PERFORM append_user_storage_delta(NEW.owner_user_id, NEW.size_bytes - OLD.size_bytes);
  END IF;
  RETURN NULL;
END;
$$;

CREATE OR REPLACE FUNCTION account_upload_reservation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  old_pending boolean := false;
  new_pending boolean := false;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    old_pending := OLD.status = 'pending';
  END IF;
  IF TG_OP <> 'DELETE' THEN
    new_pending := NEW.status = 'pending';
  END IF;

  IF old_pending AND NOT new_pending THEN
    PERFORM adjust_user_storage_reserved(
      OLD.user_id, -COALESCE(OLD.reserved_size, OLD.declared_size)
    );
  ELSIF NOT old_pending AND new_pending THEN
    PERFORM adjust_user_storage_reserved(
      NEW.user_id, COALESCE(NEW.reserved_size, NEW.declared_size)
    );
  ELSIF old_pending AND new_pending
    AND OLD.user_id IS DISTINCT FROM NEW.user_id THEN
    -- Ownership transfer moves a live reservation, and the counter has to move
    -- with it or the old owner is charged for bytes they can no longer see.
    PERFORM adjust_user_storage_reserved(
      OLD.user_id, -COALESCE(OLD.reserved_size, OLD.declared_size)
    );
    PERFORM adjust_user_storage_reserved(
      NEW.user_id, COALESCE(NEW.reserved_size, NEW.declared_size)
    );
  ELSIF old_pending AND new_pending
    AND COALESCE(OLD.reserved_size, OLD.declared_size)
      IS DISTINCT FROM COALESCE(NEW.reserved_size, NEW.declared_size) THEN
    PERFORM adjust_user_storage_reserved(
      NEW.user_id,
      COALESCE(NEW.reserved_size, NEW.declared_size)
        - COALESCE(OLD.reserved_size, OLD.declared_size)
    );
  END IF;
  RETURN NULL;
END;
$$;

CREATE OR REPLACE FUNCTION account_editor_asset_storage()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  old_ready boolean := false;
  new_ready boolean := false;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    old_ready := OLD.status = 'ready';
  END IF;
  IF TG_OP <> 'DELETE' THEN
    new_ready := NEW.status = 'ready';
  END IF;
  IF TG_OP = 'INSERT' AND new_ready THEN
    PERFORM adjust_user_storage_used(NEW.user_id, NEW.size_bytes);
  ELSIF TG_OP = 'DELETE' AND old_ready THEN
    PERFORM adjust_user_storage_used(OLD.user_id, -OLD.size_bytes);
  ELSIF TG_OP = 'UPDATE' AND OLD.user_id IS DISTINCT FROM NEW.user_id THEN
    IF old_ready THEN
      PERFORM adjust_user_storage_used(OLD.user_id, -OLD.size_bytes);
    END IF;
    IF new_ready THEN
      PERFORM adjust_user_storage_used(NEW.user_id, NEW.size_bytes);
    END IF;
  ELSIF TG_OP = 'UPDATE' AND old_ready AND NOT new_ready THEN
    PERFORM adjust_user_storage_used(OLD.user_id, -OLD.size_bytes);
  ELSIF TG_OP = 'UPDATE' AND NOT old_ready AND new_ready THEN
    PERFORM adjust_user_storage_used(NEW.user_id, NEW.size_bytes);
  ELSIF TG_OP = 'UPDATE' AND old_ready AND new_ready
    AND OLD.size_bytes IS DISTINCT FROM NEW.size_bytes THEN
    PERFORM adjust_user_storage_used(NEW.user_id, NEW.size_bytes - OLD.size_bytes);
  END IF;
  RETURN NULL;
END;
$$;

DROP TRIGGER IF EXISTS files_storage_owner_before ON files;
CREATE TRIGGER files_storage_owner_before
BEFORE INSERT OR UPDATE OF workspace_id ON files
FOR EACH ROW EXECUTE FUNCTION set_file_storage_owner();
DROP TRIGGER IF EXISTS files_cancel_pipeline_jobs_before ON files;
CREATE TRIGGER files_cancel_pipeline_jobs_before
BEFORE DELETE ON files
FOR EACH ROW EXECUTE FUNCTION cancel_file_pipeline_jobs();
DROP TRIGGER IF EXISTS files_storage_after ON files;
CREATE TRIGGER files_storage_after
AFTER INSERT OR UPDATE OR DELETE ON files
FOR EACH ROW EXECUTE FUNCTION account_file_storage();
DROP TRIGGER IF EXISTS files_blob_refs_after ON files;
CREATE TRIGGER files_blob_refs_after
AFTER INSERT OR UPDATE OF blob_path, preview_blob_path OR DELETE ON files
FOR EACH ROW EXECUTE FUNCTION account_blob_refs('blob_path', 'preview_blob_path');

-- Durable cache readers may still be downloading an object when its cache row
-- expires, so unref waits 15 minutes. Local parse handoffs never enter here;
-- only their separate parse-bundles/* B2 copies do.
CREATE OR REPLACE FUNCTION account_artifact_cache_refs()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  old_path text := CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE OLD.object_path END;
  new_path text := CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE NEW.object_path END;
BEGIN
  IF old_path IS DISTINCT FROM new_path THEN
    PERFORM blob_ref(new_path);
    PERFORM blob_unref(old_path, interval '15 minutes');
  END IF;
  RETURN NULL;
END;
$$;
DROP TRIGGER IF EXISTS artifact_cache_blob_refs_after ON artifact_cache;
CREATE TRIGGER artifact_cache_blob_refs_after
AFTER INSERT OR UPDATE OF object_path OR DELETE ON artifact_cache
FOR EACH ROW EXECUTE FUNCTION account_artifact_cache_refs();

DROP TRIGGER IF EXISTS upload_sessions_storage_owner_before ON upload_sessions;
CREATE TRIGGER upload_sessions_storage_owner_before
BEFORE INSERT OR UPDATE OF workspace_id ON upload_sessions
FOR EACH ROW EXECUTE FUNCTION set_upload_storage_owner();
DROP TRIGGER IF EXISTS upload_sessions_reservation_after ON upload_sessions;
CREATE TRIGGER upload_sessions_reservation_after
AFTER UPDATE OR DELETE ON upload_sessions
FOR EACH ROW EXECUTE FUNCTION account_upload_reservation();
DROP TRIGGER IF EXISTS upload_sessions_cancel_import_before ON upload_sessions;
CREATE TRIGGER upload_sessions_cancel_import_before
BEFORE DELETE ON upload_sessions
FOR EACH ROW EXECUTE FUNCTION cancel_source_import_on_upload_delete();
DROP TRIGGER IF EXISTS upload_sessions_blob_deletion_after ON upload_sessions;
CREATE TRIGGER upload_sessions_blob_deletion_after
AFTER DELETE ON upload_sessions
FOR EACH ROW EXECUTE FUNCTION account_upload_blob_deletion();

DROP TRIGGER IF EXISTS editor_assets_storage_owner_before ON editor_assets;
CREATE TRIGGER editor_assets_storage_owner_before
BEFORE INSERT OR UPDATE OF workspace_id, material_id ON editor_assets
FOR EACH ROW EXECUTE FUNCTION set_editor_asset_storage_owner();
DROP TRIGGER IF EXISTS editor_assets_blob_refs_after ON editor_assets;
CREATE TRIGGER editor_assets_blob_refs_after
AFTER INSERT OR UPDATE OF object_path OR DELETE ON editor_assets
FOR EACH ROW EXECUTE FUNCTION account_blob_refs('object_path');
DROP TRIGGER IF EXISTS editor_assets_storage_after ON editor_assets;
CREATE TRIGGER editor_assets_storage_after
AFTER INSERT OR UPDATE OR DELETE ON editor_assets
FOR EACH ROW EXECUTE FUNCTION account_editor_asset_storage();

DROP TRIGGER IF EXISTS materials_storage_before ON materials;
CREATE TRIGGER materials_storage_before
BEFORE INSERT OR UPDATE OF workspace_id, content ON materials
FOR EACH ROW EXECUTE FUNCTION prepare_material_storage_fields();
DROP TRIGGER IF EXISTS materials_storage_after ON materials;
CREATE TRIGGER materials_storage_after
AFTER INSERT OR UPDATE OR DELETE ON materials
FOR EACH ROW EXECUTE FUNCTION account_material_storage();

CREATE OR REPLACE FUNCTION enqueue_material_collaboration_eviction(
  target_material_id text,
  event_type text DEFAULT 'access-changed',
  eviction_mode text DEFAULT 'discard'
)
RETURNS void
LANGUAGE plpgsql
AS $$
DECLARE
  eviction_id text := 'cev_' || substr(md5(
    random()::text || clock_timestamp()::text || target_material_id
  ), 1, 24);
  room_schema int;
  room_name text;
BEGIN
  IF eviction_mode NOT IN ('discard', 'drain') THEN
    RAISE EXCEPTION 'invalid collaboration eviction mode %', eviction_mode;
  END IF;
  SELECT d.room_schema INTO room_schema
  FROM material_yjs_documents d
  WHERE d.material_id=target_material_id;
  room_name := 'material:' || target_material_id || ':schema:' || COALESCE(room_schema, 1)::text;
  INSERT INTO collaboration_eviction_outbox (id, channel, payload)
  VALUES (
    eviction_id,
    'capy:collaboration:evict',
    jsonb_build_object(
      'evictionId', eviction_id,
      'materialId', target_material_id,
      'mode', eviction_mode,
      'room', room_name,
      'type', event_type
    )
  );
END;
$$;

CREATE OR REPLACE FUNCTION enqueue_source_collaboration_eviction(target_file_id text,eviction_mode text DEFAULT 'discard')
RETURNS void LANGUAGE plpgsql AS $$
DECLARE source_epoch bigint; eviction_id text;
BEGIN
 SELECT epoch INTO source_epoch FROM source_documents WHERE file_id=target_file_id;
 IF source_epoch IS NULL THEN RETURN; END IF;
 eviction_id:='cev_'||substr(md5(random()::text||clock_timestamp()::text||target_file_id),1,24);
 INSERT INTO collaboration_eviction_outbox(id,channel,payload)
 VALUES(eviction_id,
 'capy:collaboration:evict',jsonb_build_object('evictionId',eviction_id,'fileId',target_file_id,'room','source:'||target_file_id||':epoch:'||source_epoch::text,'type','access-changed','mode',eviction_mode));
END;
$$;

CREATE OR REPLACE FUNCTION enqueue_workspace_collaboration_evictions(
  target_workspace_id text,
  eviction_mode text DEFAULT 'discard'
)
RETURNS void
LANGUAGE plpgsql
AS $$
DECLARE
  material_row record;
BEGIN
  FOR material_row IN
    SELECT id FROM materials WHERE workspace_id=target_workspace_id
  LOOP
    PERFORM enqueue_material_collaboration_eviction(
      material_row.id, 'access-changed', eviction_mode
    );
  END LOOP;
  FOR material_row IN SELECT id FROM files WHERE workspace_id=target_workspace_id LOOP
    PERFORM enqueue_source_collaboration_eviction(material_row.id,eviction_mode);
  END LOOP;
END;
$$;

CREATE OR REPLACE FUNCTION material_acl_eviction_trigger()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  eviction_mode text := 'discard';
BEGIN
  IF TG_OP='UPDATE'
    AND OLD.workspace_id IS NOT DISTINCT FROM NEW.workspace_id
    AND OLD.owner_user_id=NEW.owner_user_id
    AND (
      (OLD.privacy='private' AND NEW.privacy IN ('link','public'))
      OR (OLD.privacy='link' AND NEW.privacy='public')
    )
  THEN
    eviction_mode := 'drain';
  END IF;
  PERFORM enqueue_material_collaboration_eviction(
    CASE WHEN TG_OP='DELETE' THEN OLD.id ELSE NEW.id END,
    'access-changed',
    eviction_mode
  );
  RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END;
$$;

CREATE OR REPLACE FUNCTION workspace_acl_eviction_trigger()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  eviction_mode text := 'discard';
BEGIN
  IF OLD.user_id=NEW.user_id
    AND (
      -- A private workspace has no nonmember grant, so its dormant share role
      -- cannot turn a privacy widening into a destructive reset.
      OLD.privacy='private'
      OR (
        (CASE OLD.privacy
          WHEN 'private' THEN 0 WHEN 'link' THEN 1 WHEN 'public' THEN 2
        END) <= (CASE NEW.privacy
          WHEN 'private' THEN 0 WHEN 'link' THEN 1 WHEN 'public' THEN 2
        END)
        AND (CASE OLD.share_role
          WHEN 'viewer' THEN 0 WHEN 'commenter' THEN 1 WHEN 'editor' THEN 2
        END) <= (CASE NEW.share_role
          WHEN 'viewer' THEN 0 WHEN 'commenter' THEN 1 WHEN 'editor' THEN 2
        END)
      )
    )
  THEN
    eviction_mode := 'drain';
  END IF;
  PERFORM enqueue_workspace_collaboration_evictions(NEW.id, eviction_mode);
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION workspace_member_acl_eviction_trigger()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  eviction_mode text := 'discard';
BEGIN
  IF TG_OP='INSERT' OR (
    TG_OP='UPDATE'
    AND (CASE OLD.role
      WHEN 'viewer' THEN 0 WHEN 'commenter' THEN 1
      WHEN 'editor' THEN 2 WHEN 'owner' THEN 3
    END) <= (CASE NEW.role
      WHEN 'viewer' THEN 0 WHEN 'commenter' THEN 1
      WHEN 'editor' THEN 2 WHEN 'owner' THEN 3
    END)
  )
  THEN
    eviction_mode := 'drain';
  END IF;
  PERFORM enqueue_workspace_collaboration_evictions(
    CASE WHEN TG_OP='DELETE' THEN OLD.workspace_id ELSE NEW.workspace_id END,
    eviction_mode
  );
  RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END;
$$;

CREATE OR REPLACE FUNCTION user_acl_eviction_trigger()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  target_user_id text := CASE WHEN TG_OP='DELETE' THEN OLD.id ELSE NEW.id END;
  eviction_mode text := 'discard';
  material_event_type text := 'access-changed';
  eviction_id text := 'cev_' || substr(md5(
    random()::text || clock_timestamp()::text || target_user_id
  ), 1, 24);
  material_row record;
BEGIN
  IF TG_OP='UPDATE'
    AND NEW.deleted_at IS NULL
    AND NEW.deletion_requested_at IS NULL
    AND NEW.suspended_at IS NULL
    AND (CASE OLD.plan_tier WHEN 'free' THEN 0 WHEN 'pro' THEN 1 END)
      <= (CASE NEW.plan_tier WHEN 'free' THEN 0 WHEN 'pro' THEN 1 END)
    AND (CASE OLD.subscription_status
      WHEN 'none' THEN 0 WHEN 'canceled' THEN 0
      WHEN 'past_due' THEN 1 WHEN 'trialing' THEN 1 WHEN 'active' THEN 1
      ELSE -1
    END) <= (CASE NEW.subscription_status
      WHEN 'none' THEN 0 WHEN 'canceled' THEN 0
      WHEN 'past_due' THEN 1 WHEN 'trialing' THEN 1 WHEN 'active' THEN 1
      ELSE -1
    END)
  THEN
    eviction_mode := 'drain';
    material_event_type := 'account-access-restored';
  END IF;
  INSERT INTO collaboration_eviction_outbox (id, channel, payload)
  VALUES (
    eviction_id,
    'capy:collaboration:user-evict',
    jsonb_build_object(
      'evictionId', eviction_id,
      'mode', eviction_mode,
      'type', 'account-access-changed',
      'userId', target_user_id
    )
  );
  FOR material_row IN
    SELECT id FROM materials WHERE owner_user_id=target_user_id
  LOOP
    PERFORM enqueue_material_collaboration_eviction(
      material_row.id, material_event_type, eviction_mode
    );
  END LOOP;
  RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END;
$$;

CREATE OR REPLACE FUNCTION cleanup_clone_count_trigger()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF TG_TABLE_NAME='workspaces' THEN
    PERFORM pg_advisory_xact_lock(hashtextextended(
      'clone-source:workspace:' || OLD.id, 0
    ));
    DELETE FROM workspace_clone_counts WHERE workspace_id=OLD.id;
  ELSE
    PERFORM pg_advisory_xact_lock(hashtextextended(
      'clone-source:material:' || OLD.id, 0
    ));
    DELETE FROM material_clone_counts WHERE material_id=OLD.id;
  END IF;
  RETURN OLD;
END;
$$;

DROP TRIGGER IF EXISTS materials_acl_eviction_update ON materials;
CREATE TRIGGER materials_acl_eviction_update
AFTER UPDATE OF privacy, workspace_id, owner_user_id ON materials
FOR EACH ROW
WHEN (OLD.privacy IS DISTINCT FROM NEW.privacy
  OR OLD.workspace_id IS DISTINCT FROM NEW.workspace_id
  OR OLD.owner_user_id IS DISTINCT FROM NEW.owner_user_id)
EXECUTE FUNCTION material_acl_eviction_trigger();
DROP TRIGGER IF EXISTS materials_acl_eviction_delete ON materials;
CREATE TRIGGER materials_acl_eviction_delete
BEFORE DELETE ON materials
FOR EACH ROW EXECUTE FUNCTION material_acl_eviction_trigger();

DROP TRIGGER IF EXISTS workspaces_acl_eviction_update ON workspaces;
CREATE TRIGGER workspaces_acl_eviction_update
AFTER UPDATE OF privacy, share_role, user_id ON workspaces
FOR EACH ROW
WHEN (OLD.privacy IS DISTINCT FROM NEW.privacy
  OR OLD.share_role IS DISTINCT FROM NEW.share_role
  OR OLD.user_id IS DISTINCT FROM NEW.user_id)
EXECUTE FUNCTION workspace_acl_eviction_trigger();

DROP TRIGGER IF EXISTS workspace_members_acl_eviction_insert_update ON workspace_members;
CREATE TRIGGER workspace_members_acl_eviction_insert_update
AFTER INSERT OR UPDATE OF role ON workspace_members
FOR EACH ROW
EXECUTE FUNCTION workspace_member_acl_eviction_trigger();
DROP TRIGGER IF EXISTS workspace_members_acl_eviction_delete ON workspace_members;
CREATE TRIGGER workspace_members_acl_eviction_delete
AFTER DELETE ON workspace_members
FOR EACH ROW EXECUTE FUNCTION workspace_member_acl_eviction_trigger();

DROP TRIGGER IF EXISTS users_acl_eviction_update ON users;
CREATE TRIGGER users_acl_eviction_update
AFTER UPDATE OF deleted_at, deletion_requested_at, suspended_at, plan_tier, subscription_status ON users
FOR EACH ROW
WHEN (OLD.deleted_at IS DISTINCT FROM NEW.deleted_at
  OR OLD.deletion_requested_at IS DISTINCT FROM NEW.deletion_requested_at
  OR OLD.suspended_at IS DISTINCT FROM NEW.suspended_at
  OR OLD.plan_tier IS DISTINCT FROM NEW.plan_tier
  OR OLD.subscription_status IS DISTINCT FROM NEW.subscription_status)
EXECUTE FUNCTION user_acl_eviction_trigger();
DROP TRIGGER IF EXISTS users_acl_eviction_delete ON users;
CREATE TRIGGER users_acl_eviction_delete
BEFORE DELETE ON users
FOR EACH ROW EXECUTE FUNCTION user_acl_eviction_trigger();

DROP TRIGGER IF EXISTS workspaces_clone_count_cleanup ON workspaces;
CREATE TRIGGER workspaces_clone_count_cleanup
BEFORE DELETE ON workspaces
FOR EACH ROW EXECUTE FUNCTION cleanup_clone_count_trigger();
DROP TRIGGER IF EXISTS materials_clone_count_cleanup ON materials;
CREATE TRIGGER materials_clone_count_cleanup
BEFORE DELETE ON materials
FOR EACH ROW EXECUTE FUNCTION cleanup_clone_count_trigger();


CREATE TRIGGER source_documents_blob_refs_after
AFTER INSERT OR UPDATE OR DELETE ON source_documents
FOR EACH ROW EXECUTE FUNCTION account_blob_refs('base_blob_path');
CREATE TRIGGER source_refresh_candidates_blob_refs_after
AFTER INSERT OR UPDATE OR DELETE ON source_refresh_candidates
FOR EACH ROW EXECUTE FUNCTION account_blob_refs('source_blob_path','preview_blob_path');
CREATE TRIGGER image_caption_associations_blob_refs_after
AFTER INSERT OR UPDATE OR DELETE ON image_caption_associations
FOR EACH ROW EXECUTE FUNCTION account_blob_refs('caption_blob_path');

CREATE OR REPLACE FUNCTION set_source_storage_owner() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  SELECT user_id INTO NEW.user_id FROM files WHERE id=NEW.file_id;
  RETURN NEW;
END;
$$;
CREATE TRIGGER source_documents_owner_before BEFORE INSERT OR UPDATE OF file_id ON source_documents
FOR EACH ROW EXECUTE FUNCTION set_source_storage_owner();
CREATE TRIGGER source_refresh_candidates_owner_before BEFORE INSERT OR UPDATE OF file_id ON source_refresh_candidates
FOR EACH ROW EXECUTE FUNCTION set_source_storage_owner();
CREATE OR REPLACE FUNCTION account_source_storage() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP='INSERT' THEN
    PERFORM append_user_storage_delta(NEW.user_id,NEW.storage_bytes);
  ELSIF TG_OP='DELETE' THEN
    PERFORM append_user_storage_delta(OLD.user_id,-OLD.storage_bytes);
  ELSIF OLD.user_id IS DISTINCT FROM NEW.user_id THEN
    PERFORM append_user_storage_delta(OLD.user_id,-OLD.storage_bytes);
    PERFORM append_user_storage_delta(NEW.user_id,NEW.storage_bytes);
  ELSE
    PERFORM append_user_storage_delta(NEW.user_id,NEW.storage_bytes-OLD.storage_bytes);
  END IF;
  RETURN NULL;
END;
$$;
CREATE TRIGGER source_documents_storage_after AFTER INSERT OR UPDATE OR DELETE ON source_documents
FOR EACH ROW EXECUTE FUNCTION account_source_storage();
CREATE TRIGGER source_refresh_candidates_storage_after AFTER INSERT OR UPDATE OR DELETE ON source_refresh_candidates
FOR EACH ROW EXECUTE FUNCTION account_source_storage();
CREATE OR REPLACE FUNCTION transfer_source_storage_owner() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  UPDATE source_documents SET user_id=NEW.user_id WHERE file_id=NEW.id;
  UPDATE source_refresh_candidates SET user_id=NEW.user_id WHERE file_id=NEW.id;
  RETURN NULL;
END;
$$;
CREATE TRIGGER files_source_owner_after AFTER UPDATE OF user_id ON files
FOR EACH ROW WHEN (OLD.user_id IS DISTINCT FROM NEW.user_id) EXECUTE FUNCTION transfer_source_storage_owner();

CREATE OR REPLACE FUNCTION source_delete_eviction_trigger() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 PERFORM enqueue_source_collaboration_eviction(OLD.id,'discard');
 RETURN OLD;
END;
$$;
CREATE TRIGGER files_source_delete_eviction_before BEFORE DELETE ON files
FOR EACH ROW EXECUTE FUNCTION source_delete_eviction_trigger();

-- PostgreSQL grants function execution to PUBLIC by default. Keep operational
-- roles deny-by-default; deployment grants each narrow SECURITY DEFINER entry
-- point only to the Ops role that needs it.
REVOKE EXECUTE ON ALL FUNCTIONS IN SCHEMA public FROM PUBLIC;
